_db = _install('db', '"""Schema and connections. One writer (the sampler), many readers."""\nimport sqlite3\n\nfrom . import config\n\n_SAMPLE_DDL = """\nCREATE TABLE IF NOT EXISTS sample_{tier} (\n  ts          INTEGER NOT NULL,\n  proc_id     INTEGER NOT NULL REFERENCES proc(id),\n  cpu_avg     INTEGER NOT NULL,\n  cpu_max     INTEGER NOT NULL,\n  cpu_max_ts  INTEGER NOT NULL,\n  rss_avg     INTEGER NOT NULL,\n  rss_max     INTEGER NOT NULL,\n  nproc       INTEGER NOT NULL,\n  samples     INTEGER NOT NULL,\n  net_in      INTEGER NOT NULL DEFAULT 0,\n  net_out     INTEGER NOT NULL DEFAULT 0,\n  disk_read   INTEGER NOT NULL DEFAULT 0,\n  disk_write  INTEGER NOT NULL DEFAULT 0,\n  energy      INTEGER NOT NULL DEFAULT 0,\n  stuck       INTEGER NOT NULL DEFAULT 0,\n  PRIMARY KEY (ts, proc_id)\n) WITHOUT ROWID;\n"""\n\n# Byte and energy counters added after the first databases were already\n# recording. ALTER TABLE ADD COLUMN is cheap in SQLite (metadata only) and\n# backfills existing rows with the default, so old history keeps its CPU and\n# memory and simply reports zero for metrics that were never collected.\n_SAMPLE_COLUMNS = ("net_in", "net_out", "disk_read", "disk_write",\n                   "energy", "stuck")\n\n# Battery arrived later still. -1 means "not read", which is not 0.\n_SYSTEM_COLUMNS = (("batt_pct", -1), ("batt_draw_mw", -1),\n                   ("batt_full_mwh", 0), ("on_ac", 1))\n\n_SYSTEM_DDL = """\nCREATE TABLE IF NOT EXISTS system_{tier} (\n  ts           INTEGER PRIMARY KEY,\n  cpu_busy     INTEGER NOT NULL,\n  load1        INTEGER NOT NULL,\n  mem_used_kb  INTEGER NOT NULL,\n  mem_comp_kb  INTEGER NOT NULL,\n  swap_used_kb INTEGER NOT NULL,\n  disk_free_kb INTEGER NOT NULL,\n  samples      INTEGER NOT NULL,\n  batt_pct     INTEGER NOT NULL DEFAULT -1,\n  batt_draw_mw INTEGER NOT NULL DEFAULT -1,\n  batt_full_mwh INTEGER NOT NULL DEFAULT 0,\n  on_ac        INTEGER NOT NULL DEFAULT 1,\n  expected     INTEGER NOT NULL\n) WITHOUT ROWID;\n"""\n\n_SUPPORT_DDL = """\nCREATE TABLE IF NOT EXISTS proc (\n  id           INTEGER PRIMARY KEY,\n  exe          TEXT NOT NULL,\n  args_sig     TEXT NOT NULL,\n  cmdline_full TEXT NOT NULL,\n  is_system    INTEGER NOT NULL DEFAULT 1,\n  app          TEXT NOT NULL DEFAULT \'\',\n  UNIQUE (exe, args_sig)\n);\n\nCREATE TABLE IF NOT EXISTS watchlist (\n  pattern  TEXT PRIMARY KEY,\n  added_ts INTEGER NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS gap (\n  ts_start INTEGER PRIMARY KEY,\n  ts_end   INTEGER NOT NULL,\n  reason   TEXT NOT NULL\n) WITHOUT ROWID;\n\nCREATE TABLE IF NOT EXISTS sampler_extra (\n  pid        INTEGER PRIMARY KEY,\n  net_in     INTEGER NOT NULL,\n  net_out    INTEGER NOT NULL,\n  disk_read  INTEGER NOT NULL,\n  disk_write INTEGER NOT NULL,\n  energy     INTEGER NOT NULL,\n  stuck_run  INTEGER NOT NULL DEFAULT 0,\n  updated_ts INTEGER NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS sampler_state (\n  pid        INTEGER PRIMARY KEY,\n  start_time INTEGER NOT NULL,\n  cputime_cs INTEGER NOT NULL,\n  updated_ts INTEGER NOT NULL\n);\n"""\n\n\ndef connect(path):\n    conn = sqlite3.connect(path, timeout=10.0)\n    conn.execute("PRAGMA journal_mode=WAL")\n    conn.execute("PRAGMA synchronous=NORMAL")\n    conn.execute("PRAGMA foreign_keys=ON")\n    return conn\n\n\ndef init_schema(conn):\n    """Safe to call on every tick; every statement is IF NOT EXISTS."""\n    with conn:\n        conn.executescript(_SUPPORT_DDL)\n        for tier in config.TIERS:\n            conn.executescript(_SAMPLE_DDL.format(tier=tier.name))\n            conn.executescript(_SYSTEM_DDL.format(tier=tier.name))\n        _migrate(conn)\n\n\ndef _backfill_proc_flags(conn):\n    """Classify identities interned before the column existed.\n\n    Done from the stored command line alone, which is all the history has --\n    the parent chain that resolves a pathless process is only available at\n    sampling time. Anything unresolvable stays flagged as system, matching the\n    live classifier\'s own fallback.\n    """\n    from . import identity\n    rows = conn.execute(\n        "SELECT id, cmdline_full FROM proc WHERE is_system = 1").fetchall()\n    updates = []\n    for pid, cmdline in rows:\n        verdict = identity.is_system((cmdline or "").split(" ")[0])\n        if verdict is False:\n            updates.append((0, pid))\n    if updates:\n        conn.executemany("UPDATE proc SET is_system = ? WHERE id = ?", updates)\n\n\ndef _migrate(conn):\n    """Add columns a database created by an older version is missing.\n\n    SQLite has no ADD COLUMN IF NOT EXISTS, so the existing columns are read\n    back and only the absent ones are added. This runs on every tick, which is\n    fine -- once the columns exist it is a single PRAGMA per table and no\n    writes at all.\n    """\n    for tier in config.TIERS:\n        table = "sample_" + tier.name\n        have = set(row[1] for row in conn.execute(\n            "PRAGMA table_info(%s)" % table).fetchall())\n        for column in _SAMPLE_COLUMNS:\n            if column not in have:\n                conn.execute("ALTER TABLE %s ADD COLUMN %s INTEGER NOT NULL "\n                             "DEFAULT 0" % (table, column))\n\n        pcols = set(row[1] for row in conn.execute(\n            "PRAGMA table_info(proc)").fetchall())\n        if "app" not in pcols:\n            conn.execute("ALTER TABLE proc ADD COLUMN app TEXT NOT NULL DEFAULT \'\'")\n        if "is_system" not in pcols:\n            conn.execute("ALTER TABLE proc ADD COLUMN is_system INTEGER "\n                         "NOT NULL DEFAULT 1")\n            _backfill_proc_flags(conn)\n\n        stable = "system_" + tier.name\n        shave = set(row[1] for row in conn.execute(\n            "PRAGMA table_info(%s)" % stable).fetchall())\n        for column, default in _SYSTEM_COLUMNS:\n            if column not in shave:\n                conn.execute("ALTER TABLE %s ADD COLUMN %s INTEGER NOT NULL "\n                             "DEFAULT %d" % (stable, column, default))\n')
_archive = _install('archive', '"""Copying the database out, and putting one back.\n\nA recorded history is the only thing here that cannot be regenerated. The\nprogram can be reinstalled and the charts redrawn, but a year of samples\nexists in exactly one file, so moving that file is worth doing properly\nrather than with `cp`.\n\n`cp` is in fact the specific thing to avoid. The sampler writes every thirty\nseconds, and SQLite in WAL mode keeps recent writes in a side file; copying\nthe main database while a write is in flight produces a file that opens fine\nand is missing or torn at the end. sqlite3\'s own backup API takes a\ntransactionally consistent snapshot of a live database, so that is what this\nuses.\n"""\nimport os\nimport shutil\nimport sqlite3\nimport time\n\nfrom . import config, db\n\n# A file has to look like ours before it is allowed to replace ours. These are\n# the tables every procwatch database has had since the first version.\nREQUIRED_TABLES = ("proc", "sample_raw", "system_raw", "sampler_state")\n\n\ndef _tables(conn):\n    rows = conn.execute(\n        "SELECT name FROM sqlite_master WHERE type=\'table\'").fetchall()\n    return {row[0] for row in rows}\n\n\ndef looks_like_procwatch(path):\n    """Whether this file is a readable database with our tables in it.\n\n    Checked before a restore overwrites anything, because the failure mode\n    otherwise is losing real history to a typo in a filename.\n    """\n    if not os.path.isfile(path):\n        return False, "no such file: %s" % path\n    try:\n        conn = sqlite3.connect("file:%s?mode=ro" % path, uri=True)\n    except sqlite3.Error as error:\n        return False, "cannot open %s: %s" % (path, error)\n    try:\n        missing = [t for t in REQUIRED_TABLES if t not in _tables(conn)]\n    except sqlite3.DatabaseError as error:\n        return False, "%s is not a database: %s" % (path, error)\n    finally:\n        conn.close()\n    if missing:\n        return False, "%s is missing %s" % (path, ", ".join(missing))\n    return True, ""\n\n\ndef default_name(now=None):\n    stamp = time.strftime("%Y-%m-%d-%H%M", time.localtime(now or time.time()))\n    return "procwatch-%s.db" % stamp\n\n\ndef backup(destination, source=None):\n    """Snapshot the live database to `destination`.\n\n    Returns the path written. A directory is accepted and gets a dated\n    filename inside it, because `backup ~/Desktop` is what people type.\n    """\n    source = source or config.DB_PATH\n    if not os.path.exists(source):\n        raise RuntimeError("nothing to back up: %s does not exist" % source)\n    if os.path.isdir(destination):\n        destination = os.path.join(destination, default_name())\n    parent = os.path.dirname(os.path.abspath(destination))\n    if parent and not os.path.isdir(parent):\n        os.makedirs(parent, exist_ok=True)\n\n    live = sqlite3.connect(source)\n    out = sqlite3.connect(destination)\n    try:\n        # Consistent against a sampler that is writing underneath us.\n        live.backup(out)\n        # Copied databases are read far more than written; leaving the WAL\n        # behind in the copy means the backup is one file, not three.\n        out.execute("PRAGMA journal_mode=DELETE")\n    finally:\n        out.close()\n        live.close()\n    return destination\n\n\ndef restore(source, destination=None, keep_previous=True):\n    """Replace the live database with `source`.\n\n    The database being replaced is itself backed up first unless asked\n    otherwise: a restore is the one operation here that destroys history, and\n    restoring the wrong file should be survivable.\n\n    Returns (destination, path of the safety copy or None).\n    """\n    destination = destination or config.DB_PATH\n    ok, why = looks_like_procwatch(source)\n    if not ok:\n        raise RuntimeError("refusing to restore: %s" % why)\n    if os.path.abspath(source) == os.path.abspath(destination):\n        raise RuntimeError("source and destination are the same file")\n\n    config.ensure_dirs()\n    previous = None\n    if keep_previous and os.path.exists(destination):\n        previous = destination + ".replaced-" + time.strftime("%Y%m%d-%H%M%S")\n        shutil.copy2(destination, previous)\n\n    # Written through SQLite rather than copied over the top: the sampler may\n    # hold the destination open, and replacing the file underneath an open\n    # handle leaves that process writing to a file nobody can see. Opening the\n    # destination and overwriting its pages leaves every reader consistent.\n    incoming = sqlite3.connect("file:%s?mode=ro" % source, uri=True)\n    target = sqlite3.connect(destination)\n    try:\n        incoming.backup(target)\n    finally:\n        target.close()\n        incoming.close()\n\n    # Anything the restored file predates is re-derived rather than assumed.\n    conn = db.connect(destination)\n    try:\n        db.init_schema(conn)\n    finally:\n        conn.close()\n    return destination, previous\n\n\ndef describe(path):\n    """A one-line summary of what a database holds, for confirming a restore."""\n    ok, why = looks_like_procwatch(path)\n    if not ok:\n        return why\n    conn = sqlite3.connect("file:%s?mode=ro" % path, uri=True)\n    try:\n        rows = 0\n        oldest, newest = None, None\n        for tier in config.TIERS:\n            try:\n                row = conn.execute(\n                    "SELECT COUNT(*), MIN(ts), MAX(ts) FROM sample_%s"\n                    % tier.name).fetchone()\n            except sqlite3.Error:\n                continue\n            rows += row[0] or 0\n            if row[1]:\n                oldest = row[1] if oldest is None else min(oldest, row[1])\n                newest = row[2] if newest is None else max(newest, row[2])\n    finally:\n        conn.close()\n    size = os.path.getsize(path) / (1024.0 * 1024.0)\n    if oldest is None:\n        return "%.1f MB, no samples" % size\n    return "%.1f MB, %d samples, %s to %s" % (\n        size, rows,\n        time.strftime("%Y-%m-%d", time.localtime(oldest)),\n        time.strftime("%Y-%m-%d", time.localtime(newest)))\n')
_alerts = _install('alerts', '"""Rules that watch the recording and say something when they are met.\n\nprocwatch records everything and never speaks. That is the gap this closes:\nthe question that started the tool -- "why is my Mac slow" -- is one it could\nhave answered before being asked, if anything had been watching.\n\nA rule is deliberately small: a metric, a threshold, and how long it has to\nhold. "Anything above 80% CPU for ten minutes" catches a runaway; "above 80%\nfor one sample" catches a compiler starting up, which is not news. Sustain is\nwhat separates a problem from a spike, so it is not optional.\n\nEvaluated by the recorder, once per tick, against rows it has just written.\nNothing here polls, and nothing needs the dashboard to be open.\n"""\nimport json\nimport subprocess\nimport time\n\nfrom . import config, db\n\n# Metrics a rule can watch. Each maps to a column the sampler already writes,\n# with the scale it is stored at, so a rule states its threshold in the unit a\n# person would say out loud.\nMETRICS = {\n    "cpu":    {"column": "cpu_avg",   "scale": 10.0,  "unit": "%"},\n    "memory": {"column": "rss_avg",   "scale": 1024.0, "unit": "MB"},\n    "disk":   {"column": "disk_read + disk_write", "scale": 1048576.0,\n               "unit": "MB/s", "rate": True},\n    "net":    {"column": "net_in + net_out", "scale": 1048576.0,\n               "unit": "MB/s", "rate": True},\n}\n\nDDL = """\nCREATE TABLE IF NOT EXISTS alert_rule (\n  id        INTEGER PRIMARY KEY,\n  pattern   TEXT NOT NULL,\n  metric    TEXT NOT NULL,\n  threshold REAL NOT NULL,\n  sustain   INTEGER NOT NULL,\n  enabled   INTEGER NOT NULL DEFAULT 1,\n  added_ts  INTEGER NOT NULL,\n  UNIQUE (pattern, metric, threshold, sustain)\n);\n\nCREATE TABLE IF NOT EXISTS alert_event (\n  id        INTEGER PRIMARY KEY,\n  rule_id   INTEGER NOT NULL,\n  proc_id   INTEGER NOT NULL,\n  ts        INTEGER NOT NULL,\n  value     REAL NOT NULL,\n  notified  INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS alert_event_ts ON alert_event (ts);\n"""\n\n# Once a rule has fired for a process, it stays quiet about that process for\n# this long. A runaway that lasts an hour is one piece of news, not 120.\nREARM = 1800\n\n\ndef init(conn):\n    with conn:\n        conn.executescript(DDL)\n\n\ndef add(conn, pattern, metric, threshold, sustain):\n    if metric not in METRICS:\n        raise ValueError("unknown metric %r; try %s"\n                         % (metric, ", ".join(sorted(METRICS))))\n    if sustain < config.INTERVAL:\n        raise ValueError("sustain must be at least one sample (%ds)"\n                         % config.INTERVAL)\n    init(conn)\n    with conn:\n        conn.execute(\n            "INSERT OR IGNORE INTO alert_rule "\n            "(pattern, metric, threshold, sustain, added_ts) VALUES (?,?,?,?,?)",\n            (pattern, metric, float(threshold), int(sustain), int(time.time())))\n    return rules(conn)\n\n\ndef remove(conn, rule_id):\n    init(conn)\n    with conn:\n        cur = conn.execute("DELETE FROM alert_rule WHERE id = ?", (rule_id,))\n    return cur.rowcount > 0\n\n\ndef rules(conn):\n    init(conn)\n    return [dict(id=r[0], pattern=r[1], metric=r[2], threshold=r[3],\n                 sustain=r[4], enabled=bool(r[5]))\n            for r in conn.execute(\n                "SELECT id, pattern, metric, threshold, sustain, enabled "\n                "FROM alert_rule ORDER BY id").fetchall()]\n\n\ndef _matches(pattern, exe, app):\n    """A rule\'s pattern against an identity.\n\n    Substring, case-insensitive, and "*" means everything -- because the rule\n    people actually want first is "tell me about anything", and making them\n    learn a syntax to express it would be a poor trade.\n    """\n    if pattern == "*":\n        return True\n    needle = pattern.lower()\n    return needle in (exe or "").lower() or needle in (app or "").lower()\n\n\ndef evaluate(conn, now=None):\n    """Check every enabled rule against the samples just written.\n\n    Returns the events raised. Reads only the raw tier and only the window a\n    rule asks for, so the cost is bounded by the longest sustain rather than\n    by the size of the history.\n    """\n    init(conn)\n    now = int(time.time()) if now is None else now\n    active = [r for r in rules(conn) if r["enabled"]]\n    if not active:\n        return []\n\n    raised = []\n    for rule in active:\n        spec = METRICS[rule["metric"]]\n        window = max(rule["sustain"], config.INTERVAL)\n        start = now - window\n        # Every sample in the window must be over the threshold, and there\n        # must be enough of them to cover it -- otherwise a process that\n        # reported once, highly, would look like it had sustained anything.\n        needed = max(1, window // config.INTERVAL)\n        rows = conn.execute(\n            "SELECT proc_id, COUNT(*), MIN(%s), AVG(%s) "\n            "FROM sample_raw WHERE ts > ? AND ts <= ? "\n            "GROUP BY proc_id HAVING COUNT(*) >= ? AND MIN(%s) > ?"\n            % (spec["column"], spec["column"], spec["column"]),\n            (start, now, needed, rule["threshold"] * spec["scale"])).fetchall()\n        if not rows:\n            continue\n        ids = [r[0] for r in rows]\n        names = {r[0]: (r[1], r[2]) for r in conn.execute(\n            "SELECT id, exe, app FROM proc WHERE id IN (%s)"\n            % ",".join("?" * len(ids)), ids).fetchall()}\n        for proc_id, _count, _low, mean in rows:\n            exe, app = names.get(proc_id, ("", ""))\n            if exe == config.OTHER or not _matches(rule["pattern"], exe, app):\n                continue\n            recent = conn.execute(\n                "SELECT MAX(ts) FROM alert_event WHERE rule_id = ? AND proc_id = ?",\n                (rule["id"], proc_id)).fetchone()[0]\n            if recent and now - recent < REARM:\n                continue\n            value = mean / spec["scale"]\n            with conn:\n                conn.execute(\n                    "INSERT INTO alert_event (rule_id, proc_id, ts, value) "\n                    "VALUES (?,?,?,?)", (rule["id"], proc_id, now, value))\n            raised.append({"rule": rule, "exe": exe, "app": app,\n                           "ts": now, "value": value, "unit": spec["unit"]})\n    return raised\n\n\ndef notify(event):\n    """Put an alert on screen, via the notification centre.\n\n    osascript rather than a framework binding: it is the only way to post a\n    macOS notification without a signed bundle, and this has to work when\n    procwatch is a single Python file that was curled from the internet.\n    """\n    title = "%s %s" % (event["exe"], event["rule"]["metric"])\n    body = "%s at %.1f%s for %s" % (\n        event["app"] or event["exe"], event["value"], event["unit"],\n        _duration(event["rule"]["sustain"]))\n    try:\n        subprocess.run(\n            ["osascript", "-e",\n             \'display notification %s with title %s\'\n             % (json.dumps(body), json.dumps(title))],\n            capture_output=True, timeout=10)\n    except (OSError, subprocess.TimeoutExpired):\n        pass          # a missed notification is not worth failing a tick over\n\n\ndef _duration(seconds):\n    if seconds >= 3600:\n        return "%g hours" % round(seconds / 3600.0, 1)\n    if seconds >= 60:\n        return "%d minutes" % (seconds // 60)\n    return "%d seconds" % seconds\n\n\ndef recent(conn, limit=50):\n    init(conn)\n    rows = conn.execute(\n        "SELECT e.ts, e.value, p.exe, p.app, r.metric, r.threshold, r.sustain "\n        "FROM alert_event e JOIN proc p ON p.id = e.proc_id "\n        "JOIN alert_rule r ON r.id = e.rule_id "\n        "ORDER BY e.ts DESC LIMIT ?", (limit,)).fetchall()\n    return [dict(ts=r[0], value=r[1], exe=r[2], app=r[3], metric=r[4],\n                 threshold=r[5], sustain=r[6],\n                 unit=METRICS.get(r[4], {}).get("unit", ""))\n            for r in rows]\n')
_storage = _install('storage', '"""How much disk each application occupies.\n\nEvery other metric here is a rate sampled every thirty seconds. This one is a\nsize, it changes slowly, and measuring it means walking directories -- so it\nruns at most once a day and is stored as a plain snapshot rather than folded\ninto the sample tiers. Putting it through the same machinery would cost a\nfilesystem walk every thirty seconds to record a number that moves once a week.\n\n"An application" here means three places: the bundle itself, its Application\nSupport directory, and its caches. That is what someone means by "how much\nspace is Slack using" -- the .app alone is the download size and misses the\ngigabytes of cached messages that are the actual answer.\n"""\nimport os\nimport time\n\nfrom . import config\n\nDAY = 86400\n\nDDL = """\nCREATE TABLE IF NOT EXISTS storage (\n  app        TEXT NOT NULL,\n  kind       TEXT NOT NULL,\n  bytes      INTEGER NOT NULL,\n  ts         INTEGER NOT NULL,\n  PRIMARY KEY (app, kind)\n) WITHOUT ROWID;\n"""\n\n# Where an application\'s own data lives, by convention. Anything outside these\n# is somebody else\'s file, and guessing wider would attribute a shared cache\n# to whichever app was scanned first.\nROOTS = [\n    ("bundle", "/Applications"),\n    ("support", os.path.expanduser("~/Library/Application Support")),\n    ("caches", os.path.expanduser("~/Library/Caches")),\n]\n\n# A walk that never finishes is worse than no number. Anything deeper than\n# this is inside a package\'s own package and is counted by size regardless --\n# the limit bounds recursion, not accuracy.\nMAX_DEPTH = 12\n\n\ndef init(conn):\n    with conn:\n        conn.executescript(DDL)\n\n\ndef _tree_bytes(path, depth=0):\n    """Bytes on disk under a path, following no symlinks.\n\n    Symlinks are skipped rather than followed: /Applications is full of links\n    into the same bundle, and following them counts the target repeatedly and\n    can loop forever.\n    """\n    total = 0\n    if depth > MAX_DEPTH:\n        return total\n    try:\n        with os.scandir(path) as entries:\n            for entry in entries:\n                try:\n                    if entry.is_symlink():\n                        continue\n                    if entry.is_dir(follow_symlinks=False):\n                        total += _tree_bytes(entry.path, depth + 1)\n                    else:\n                        # st_blocks is what the disk actually gave up, which is\n                        # the number a person checking free space cares about.\n                        stat = entry.stat(follow_symlinks=False)\n                        total += getattr(stat, "st_blocks", 0) * 512 or stat.st_size\n                except (OSError, ValueError):\n                    continue          # vanished mid-walk, or not permitted\n    except (OSError, ValueError):\n        return total\n    return total\n\n\ndef _app_name(entry_name, kind):\n    if kind == "bundle":\n        return entry_name[:-4] if entry_name.endswith(".app") else None\n    return entry_name\n\n\ndef scan(conn, now=None, roots=None):\n    """Measure every application and store one row per app per kind."""\n    init(conn)\n    now = int(time.time()) if now is None else now\n    rows = []\n    for kind, root in (roots or ROOTS):\n        if not os.path.isdir(root):\n            continue\n        try:\n            names = sorted(os.listdir(root))\n        except OSError:\n            continue\n        for name in names:\n            if name.startswith("."):\n                continue\n            path = os.path.join(root, name)\n            # The root entry needs the same symlink check as everything below\n            # it: /Applications routinely holds links to bundles that live\n            # elsewhere, and counting one twice is worse than missing it.\n            if os.path.islink(path):\n                continue\n            app = _app_name(name, kind)\n            if not app:\n                continue\n            size = _tree_bytes(path)\n            if size:\n                rows.append((app, kind, size, now))\n    with conn:\n        conn.executemany(\n            "INSERT OR REPLACE INTO storage (app, kind, bytes, ts) "\n            "VALUES (?,?,?,?)", rows)\n    return len(rows)\n\n\ndef due(conn, now=None, every=DAY):\n    """Whether a scan is worth doing. Sizes move slowly; walks are expensive."""\n    init(conn)\n    now = int(time.time()) if now is None else now\n    last = conn.execute("SELECT MAX(ts) FROM storage").fetchone()[0]\n    return last is None or now - last >= every\n\n\ndef usage(conn, limit=25):\n    """Per application, largest first, with the parts that make up each total."""\n    init(conn)\n    rows = conn.execute(\n        "SELECT app, kind, bytes, ts FROM storage").fetchall()\n    apps = {}\n    for app, kind, size, ts in rows:\n        entry = apps.setdefault(app, {"app": app, "total": 0, "ts": ts,\n                                      "bundle": 0, "support": 0, "caches": 0})\n        entry[kind] = size\n        entry["total"] += size\n        entry["ts"] = max(entry["ts"], ts)\n    out = sorted(apps.values(), key=lambda a: -a["total"])\n    # An entry that exists only as a cache directory is usually not an app at\n    # all -- it is a bundle identifier -- so it is kept but not promoted.\n    return out[:limit]\n')
_appbuild = _install('appbuild', '"""Build and install the menu bar app on the machine that will run it.\n\nThe one-line installer fetches two files: this program and the installer. That\nleft the menu bar app -- the part most people actually look at -- available\nonly to someone who cloned the repository, which is a strange thing to ask of\nsomeone who has just been told the install is one command.\n\nAttaching a prebuilt .app to each release would be the obvious fix and is the\nwrong one: a downloaded bundle that is not signed and notarised is quarantined,\nand macOS refuses to open it at all. Compiling on the machine that will run it\nproduces a bundle with no quarantine attribute, so it simply opens. That is\nworth carrying a few kilobytes of Swift for.\n\nThe sources live in menubar/ in a checkout and are embedded in the single-file\nbuild, so both forms can do this.\n"""\nimport base64\nimport os\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\n\nAPP_NAME = "Procwatch.app"\n# 1.0.0 and 1.1.x installed it under this name. Left behind, it is a second\n# icon in Launchpad running an older copy.\nSUPERSEDED = ("ProcwatchBar.app",)\n\n# Filled in by the generated single-file build. In a checkout these stay empty\n# and the files are read from menubar/ instead.\nEMBEDDED = {}\n\nINFO_PLIST = """<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN"\n "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n<plist version="1.0"><dict>\n  <key>CFBundleName</key><string>Procwatch</string>\n  <key>CFBundleIdentifier</key><string>dev.procwatch.bar</string>\n  <key>CFBundleExecutable</key><string>ProcwatchBar</string>\n  <key>CFBundlePackageType</key><string>APPL</string>\n  <key>CFBundleShortVersionString</key><string>1.1.1</string>\n  <key>CFBundleIconFile</key><string>procwatch</string>\n  <key>LSUIElement</key><true/>\n  <key>NSLocalNetworkUsageDescription</key>\n  <string>Procwatch reads the history of other Macs you have added, on your local network.</string>\n  <key>NSAppTransportSecurity</key>\n  <dict><key>NSAllowsLocalNetworking</key><true/></dict>\n</dict></plist>\n"""\n\nASSETS = ("ProcwatchBar.swift", "icon.png", "procwatch-bar.png")\n\n# Every size a bundle icon is asked for. Generated from one master rather than\n# shipped as a .icns, which weighs 2.2 MB -- most of a file people are told to\n# fetch with curl.\nICON_SIZES = (16, 32, 128, 256, 512)\n\n\ndef _repo_menubar():\n    """menubar/ beside the package, when running from a checkout."""\n    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n    path = os.path.join(root, "menubar")\n    return path if os.path.isdir(path) else None\n\n\ndef asset(name):\n    """One build input, as bytes, from wherever this copy keeps them."""\n    folder = _repo_menubar()\n    if folder:\n        path = os.path.join(folder, name)\n        if os.path.exists(path):\n            with open(path, "rb") as handle:\n                return handle.read()\n    if name in EMBEDDED:\n        return base64.b64decode(EMBEDDED[name])\n    raise RuntimeError("missing build input: %s" % name)\n\n\ndef have_swift():\n    return shutil.which("swiftc") is not None\n\n\ndef program_path():\n    """The installed procwatch.py to put inside the bundle.\n\n    The app runs the server out of its own Resources so it works wherever it\n    is dragged; that copy has to come from somewhere. A checkout generates it,\n    a bundle is it.\n    """\n    entry = os.path.abspath(sys.argv[0]) if sys.argv and sys.argv[0] else ""\n    if entry.endswith(".py") and os.path.isfile(entry):\n        package = sys.modules.get(__package__ or "procwatch")\n        if not getattr(package, "__path__", None):\n            return entry                      # the single-file build itself\n    root = _repo_menubar()\n    if root:\n        generated = os.path.join(os.path.dirname(root), "procwatch.py")\n        if os.path.isfile(generated):\n            return generated\n    raise RuntimeError(\n        "cannot find procwatch.py to place inside the app; run "\n        "tools/bundle.py first, or install with the one-line installer")\n\n\ndef build(destination="/Applications"):\n    """Compile the app and install it. Returns the installed path."""\n    if sys.platform != "darwin":\n        raise RuntimeError("the menu bar app is macOS only")\n    if not have_swift():\n        raise RuntimeError(\n            "swiftc not found. Install the Command Line Tools:\\n"\n            "  xcode-select --install")\n\n    program = program_path()\n    work = tempfile.mkdtemp(prefix="procwatch-app-")\n    app = os.path.join(work, APP_NAME)\n    macos = os.path.join(app, "Contents", "MacOS")\n    resources = os.path.join(app, "Contents", "Resources")\n    os.makedirs(macos)\n    os.makedirs(resources)\n    try:\n        source = os.path.join(work, "ProcwatchBar.swift")\n        with open(source, "wb") as handle:\n            handle.write(asset("ProcwatchBar.swift"))\n        result = subprocess.run(\n            ["swiftc", "-O", source, "-o", os.path.join(macos, "ProcwatchBar"),\n             "-framework", "AppKit", "-framework", "WebKit"],\n            capture_output=True, text=True, timeout=600)\n        if result.returncode != 0:\n            raise RuntimeError("swiftc failed:\\n%s"\n                               % (result.stderr or result.stdout).strip()[:800])\n\n        with open(os.path.join(app, "Contents", "Info.plist"), "w") as handle:\n            handle.write(INFO_PLIST)\n        _write_icon(work, resources)\n        with open(os.path.join(resources, "procwatch-bar.png"), "wb") as handle:\n            handle.write(asset("procwatch-bar.png"))\n        shutil.copy2(program, os.path.join(resources, "procwatch.py"))\n\n        # swiftc\'s linker signature covers the binary but not the bundle, so\n        # Info.plist is unbound: macOS has no usage description to show and no\n        # identity to remember a decision against, and the app never appears\n        # under Local Network. An ad-hoc signature over the bundle fixes both\n        # and needs no certificate.\n        try:\n            subprocess.run(["codesign", "--force", "--sign", "-",\n                            "--identifier", "dev.procwatch.bar", app],\n                           capture_output=True, timeout=120)\n        except (OSError, subprocess.TimeoutExpired):\n            pass          # unsigned still runs; it just cannot be granted\n\n        target = os.path.join(destination, APP_NAME)\n        _quit_running()\n        for old in SUPERSEDED:\n            shutil.rmtree(os.path.join(destination, old), ignore_errors=True)\n        shutil.rmtree(target, ignore_errors=True)\n        shutil.copytree(app, target)\n        return target\n    finally:\n        shutil.rmtree(work, ignore_errors=True)\n\n\ndef _write_icon(work, resources):\n    """Turn the master PNG into procwatch.icns using the tools macOS ships.\n\n    If either tool is missing the app is still built and installed -- it\n    simply shows a generic icon in Finder, which is a far better outcome than\n    refusing to build over a picture.\n    """\n    master = os.path.join(work, "icon.png")\n    with open(master, "wb") as handle:\n        handle.write(asset("icon.png"))\n    iconset = os.path.join(work, "procwatch.iconset")\n    os.makedirs(iconset, exist_ok=True)\n    try:\n        for side in ICON_SIZES:\n            for scale, suffix in ((1, ""), (2, "@2x")):\n                out = os.path.join(iconset, "icon_%dx%d%s.png"\n                                   % (side, side, suffix))\n                subprocess.run(["sips", "-z", str(side * scale), str(side * scale),\n                                master, "--out", out],\n                               capture_output=True, timeout=60)\n        result = subprocess.run(\n            ["iconutil", "-c", "icns", iconset,\n             "-o", os.path.join(resources, "procwatch.icns")],\n            capture_output=True, timeout=120)\n        if result.returncode == 0:\n            return\n    except (OSError, subprocess.TimeoutExpired):\n        pass\n    # No .icns: the bundle still runs, and the menu bar image is separate.\n    shutil.copy2(master, os.path.join(resources, "procwatch.png"))\n\n\ndef _quit_running():\n    """Ask a running copy to exit before its bundle is replaced.\n\n    Replacing the bundle underneath a live process leaves it running from a\n    directory that no longer exists, which looks like the new build failing to\n    take effect.\n    """\n    for command in (["osascript", "-e", \'quit app "Procwatch"\'],\n                    ["pkill", "-f", "Procwatch.app/Contents/MacOS/ProcwatchBar"],\n                    ["pkill", "-f", "ProcwatchBar.app/Contents/MacOS/ProcwatchBar"]):\n        try:\n            subprocess.run(command, capture_output=True, timeout=15)\n        except (OSError, subprocess.TimeoutExpired):\n            pass\n\n\ndef launch(path):\n    try:\n        subprocess.run(["open", "-a", path], capture_output=True, timeout=20)\n    except (OSError, subprocess.TimeoutExpired):\n        pass\n')
_share = _install('share', '"""Let another machine read this one\'s history, over the network.\n\nA separate listener from the dashboard, on its own port, and deliberately not\nthe same server with a flag flipped. The dashboard can end processes and hand\nout a copy of the database; this can do neither, because those code paths are\nnot reachable from here at all. The worst anyone who guesses the key can do is\nsee which applications you run.\n\nThe key is three words. Three words are long enough to be unguessable and\nshort enough to read down a phone -- which is what actually happens when\nsomeone is setting up a second machine. They come from the system dictionary,\nwhich macOS ships: 33,000 words of four to six letters gives about 45 bits,\ncomfortably beyond guessing, and no wordlist has to travel in the program.\n"""\nimport hmac\nimport json\nimport os\nimport secrets\nimport threading\nimport time\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import parse_qs, urlparse\n\nfrom . import config, db\n\nDEFAULT_PORT = 8791\nHEADER = "X-Procwatch-Key"\n\nDDL = """\nCREATE TABLE IF NOT EXISTS share_key (\n  id       INTEGER PRIMARY KEY CHECK (id = 1),\n  key      TEXT NOT NULL,\n  made_ts  INTEGER NOT NULL\n);\n"""\n\n# Enough that a wrong guess is never worth repeating, short enough that a\n# person mistyping their own key is not punished for a minute.\nLOCKOUT_AFTER = 5\nLOCKOUT_SECONDS = 60\n\n_failures = {}\n_failures_lock = threading.Lock()\n\n\ndef _wordlist():\n    """Words a person can read down a phone.\n\n    The system dictionary has 33,000 usable words and would give more bits,\n    but they are words like "exaudi", "solyma" and "peepy" -- and a key that\n    cannot be dictated is a key that gets written on a sticky note. This list\n    is short, common and unambiguous. Three of them is around 340 million\n    combinations, which matters only alongside the lockout below: five wrong\n    answers buys a minute of silence, so guessing runs at five attempts a\n    minute rather than as fast as a machine can ask.\n    """\n    return ("able acid aged also area army away baby back ball band bank base "\n            "bath bear beat been beer bell belt bend bike bird bite blue boat "\n            "body bone book boot born both bowl cake call calm camp card care "\n            "cart case cash cast cave cell chat chip city clay clip club coal "\n            "coat code coin cold cook cool copy cord corn cost crew crop dark "\n            "data date dawn deal deep deer desk dial dirt dish dock dome door "\n            "dose down draw drum dust duty each earn east easy edge exit face "\n            "fact fade fair fall farm fast fear feed feel fell file fill film "\n            "find fine fire fish flag flat flow foam fold folk food foot fork "\n            "form fort four free frog fuel full gain game gate gear gift girl "\n            "give glad glow goal gold golf gone good gray grew grid grip grow "\n            "hail hair half hall hand hang hard harm heat held help herb hero "\n            "hide high hill hint hold hole home hood hope horn host hour huge "\n            "hunt idea inch iron item jazz join jump just keep kind king knee "\n            "knot know lace lake lamp land lane last late lawn lead leaf lean "\n            "left lend lens life lift line link lion list live load loan lock "\n            "long look loop lord lost loud love luck lung made mail main make "\n            "many maps mark mask mast meal meat meet melt mend menu mesh mile "\n            "milk mill mind mine mint miss mist moon more moss most move much "\n            "name near neat neck need nest news next nice node none noon nose "\n            "note oath odds okay omit once open oven over pace pack page pain "\n            "pair palm park part pass past path peak pear peel pick pier pile "\n            "pine pink pipe plan play plot plug plus poem poet pole polo pond "\n            "pool poor port post pull pump pure push quiz race rack rail rain "\n            "rake ramp rank rare rate read real reed reef rely rest rice rich "\n            "ride ring rise risk road roar rock role roll roof room root rope "\n            "rose rule rush safe sail salt sand save scan seal seat seed seek "\n            "self sell send shed ship shoe shop shot show sick side sign silk "\n            "sing sink site size skin sky slab sled slip slow snap snow soap "\n            "sock soft soil sold sole solo song soon sort soul soup sour span "\n            "spin spot star stay stem step stir stop sung sure surf swim tale "\n            "talk tall tank tape task team tell tent term test text than that "\n            "thin this tide tidy tile till time tiny tone took tool torn tour "\n            "town trap tray tree trim trip true tube tune turn twin type unit "\n            "upon used vase vast verb very vest view vine visa void volt vote "\n            "wage wait wake walk wall want ward warm wash wave weak wear week "\n            "well went were west what when whom wide wife wild will wind wine "\n            "wing wire wise wish wolf wood wool word wore work worm wrap yard "\n            "yarn year yoga zone zoom").split()\n\n\nWORDS_FILE = None      # kept out of the key deliberately; see _wordlist\n\n\ndef local_address():\n    """This machine\'s address on the local network.\n\n    Wanted so the address can be copied off the screen rather than hunted for\n    in System Settings. Found by opening a UDP socket towards an address that\n    is never contacted -- no packet is sent, but the kernel has to choose a\n    route, and the interface it picks is the one another machine on this\n    network would reach us on. Reading en0 directly would be wrong on a Mac\n    using wi-fi and ethernet, or a VPN.\n    """\n    import socket\n    probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n    try:\n        probe.connect(("192.0.2.1", 9))      # reserved for documentation\n        return probe.getsockname()[0]\n    except OSError:\n        return ""\n    finally:\n        probe.close()\n\n\n# Where a Mac keeps the Tailscale command, depending on how it was installed.\nTAILSCALE_PATHS = (\n    "/usr/local/bin/tailscale",\n    "/opt/homebrew/bin/tailscale",\n    "/Applications/Tailscale.app/Contents/MacOS/Tailscale",\n)\n\n\ndef tailscale_address():\n    """This machine\'s address on its private network, if it has one.\n\n    Detected two ways because either can be true on its own: the command line\n    tool is missing from a Mac App Store install, and the interface can be up\n    while the tool is not on PATH.\n\n    100.64.0.0/10 is the range Tailscale allocates from. Nothing else on a\n    normal Mac uses it, so an interface address inside it is the answer even\n    when the command cannot be found.\n    """\n    import subprocess\n    for path in TAILSCALE_PATHS:\n        if not os.path.exists(path):\n            continue\n        try:\n            out = subprocess.run([path, "ip", "-4"], capture_output=True,\n                                 text=True, timeout=8)\n        except (OSError, subprocess.TimeoutExpired):\n            continue\n        first = (out.stdout or "").strip().split("\\n")[0].strip()\n        if first.startswith("100."):\n            return first\n    try:\n        out = subprocess.run(["ifconfig"], capture_output=True, text=True,\n                             timeout=8).stdout\n    except (OSError, subprocess.TimeoutExpired):\n        return ""\n    import re\n    for found in re.findall(r"inet (100\\.\\d+\\.\\d+\\.\\d+)", out):\n        octet = int(found.split(".")[1])\n        if 64 <= octet <= 127:               # 100.64.0.0/10\n            return found\n    return ""\n\n\ndef make_key(words=3):\n    """Three words, chosen with the system\'s cryptographic randomness."""\n    pool = _wordlist()\n    return "-".join(secrets.choice(pool) for _ in range(words))\n\n\ndef key(conn, reset=False):\n    """This machine\'s key, made on first use and kept."""\n    with conn:\n        conn.executescript(DDL)\n    row = None if reset else conn.execute(\n        "SELECT key FROM share_key WHERE id = 1").fetchone()\n    if row:\n        return row[0]\n    fresh = make_key()\n    with conn:\n        conn.execute("INSERT OR REPLACE INTO share_key (id, key, made_ts) "\n                     "VALUES (1, ?, ?)", (fresh, int(time.time())))\n    return fresh\n\n\ndef _locked_out(who):\n    with _failures_lock:\n        count, until = _failures.get(who, (0, 0))\n        return time.time() < until\n\n\ndef _note_failure(who):\n    with _failures_lock:\n        count, until = _failures.get(who, (0, 0))\n        count += 1\n        if count >= LOCKOUT_AFTER:\n            _failures[who] = (0, time.time() + LOCKOUT_SECONDS)\n        else:\n            _failures[who] = (count, until)\n\n\ndef _note_success(who):\n    with _failures_lock:\n        _failures.pop(who, None)\n\n\nclass ShareHandler(BaseHTTPRequestHandler):\n    """Reads only.\n\n    There is no do_POST here and no route to the dashboard, the backup or the\n    export. Adding one later would be the mistake this whole file exists to\n    avoid: the point is not that dangerous things are switched off, it is that\n    they are not present.\n    """\n\n    def log_message(self, *args):\n        pass\n\n    def _send(self, code, body):\n        payload = body.encode() if isinstance(body, str) else body\n        self.send_response(code)\n        self.send_header("Content-Type", "application/json")\n        self.send_header("Content-Length", str(len(payload)))\n        self.send_header("Cache-Control", "no-store")\n        self.end_headers()\n        self.wfile.write(payload)\n\n    def do_GET(self):\n        who = self.client_address[0]\n        if _locked_out(who):\n            return self._send(429, json.dumps(\n                {"error": "too many wrong keys; try again in a minute"}))\n        offered = self.headers.get(HEADER) or ""\n        if not hmac.compare_digest(offered, self.server.share_key):\n            _note_failure(who)\n            # A pause on every wrong answer, so guessing costs real time\n            # rather than being limited by how fast a laptop can ask.\n            time.sleep(0.5)\n            return self._send(401, json.dumps({"error": "wrong or missing key"}))\n        _note_success(who)\n\n        parsed = urlparse(self.path)\n        params = parse_qs(parsed.query)\n        from . import server                       # imported late: server imports us\n        conn = db.connect(config.DB_PATH)\n        try:\n            payload = server.api_get(conn, parsed.path, params)\n            if payload is None:\n                return self._send(404, json.dumps({"error": "unknown path"}))\n            self._send(200, json.dumps(payload))\n        except ValueError as error:\n            self._send(400, json.dumps({"error": str(error)}))\n        finally:\n            conn.close()\n\n\ndef serve(port=DEFAULT_PORT, host="0.0.0.0", reset=False):\n    conn = db.connect(config.DB_PATH)\n    try:\n        secret = key(conn, reset=reset)\n    finally:\n        conn.close()\n    httpd = ThreadingHTTPServer((host, port), ShareHandler)\n    httpd.share_key = secret\n    print("Sharing this Mac\'s history on port %d." % port)\n    print("On the other machine, add this one with:")\n    print("  procwatch peer add %s <this-mac-address>:%d --key %s"\n          % (os.uname().nodename.split(".")[0].lower(), port, secret))\n    print("\\nRead-only: no process can be ended and no database copied "\n          "through this port.")\n    httpd.serve_forever()\n    return 0\n')
_peers = _install('peers', '"""Other Macs running the recorder.\n\nEach machine still records for itself, into its own database; nothing is\ncentralised. What this adds is that one dashboard can ask another machine for\nits answers.\n\nThe machine being watched runs `procwatch share`, which opens a read-only\nlistener and prints a three-word key. The machine doing the watching stores\nthe address and the key. That is the whole arrangement: no accounts, no\ncertificates, no shell access.\n\nReads only, and not because a flag says so -- the listener on the other side\nhas no route to anything that can end a process or copy a database. So the\nworst case, if a key leaks, is that someone learns which applications you run.\n"""\nimport json\nimport os\nimport time\nimport urllib.error\nimport urllib.request\nfrom urllib.parse import urlencode\n\nfrom . import config, share\n\nDDL = """\nCREATE TABLE IF NOT EXISTS peer (\n  name      TEXT PRIMARY KEY,\n  host      TEXT NOT NULL,\n  key       TEXT NOT NULL DEFAULT \'\',\n  added_ts  INTEGER NOT NULL\n);\n"""\n\n# Long enough for a year-wide query over wi-fi, short enough that a machine\n# that is asleep does not hold up the page.\nTIMEOUT = 30\n\n\ndef _db():\n    from . import db\n    conn = db.connect(config.DB_PATH)\n    with conn:\n        conn.executescript(DDL)\n        # Databases from the SSH version have a `program` column and no `key`.\n        columns = {r[1] for r in conn.execute("PRAGMA table_info(peer)")}\n        if "key" not in columns:\n            conn.execute("ALTER TABLE peer ADD COLUMN key TEXT NOT NULL DEFAULT \'\'")\n    return conn\n\n\ndef normalise(host):\n    """Accept what people actually type.\n\n    "192.168.1.42", "192.168.1.42:8791", "http://192.168.1.42:8791" and\n    "laptop.local" all mean the same thing, and being told off for the wrong\n    one is a poor first experience of a feature whose whole point is that it\n    is simple.\n    """\n    host = (host or "").strip().rstrip("/")\n    if not host:\n        raise ValueError("a device needs an address")\n    if "://" not in host:\n        host = "http://" + host\n    if host.count(":") < 2:                       # no port given\n        host = "%s:%d" % (host, share.DEFAULT_PORT)\n    return host\n\n\ndef add(name, host, key=""):\n    if not name:\n        raise ValueError("a device needs a name")\n    if name.lower() == "this mac":\n        raise ValueError("that name is reserved for the local machine")\n    host = normalise(host)\n    conn = _db()\n    try:\n        with conn:\n            conn.execute(\n                "INSERT OR REPLACE INTO peer (name, host, key, added_ts) "\n                "VALUES (?,?,?,?)", (name, host, key.strip(), int(time.time())))\n    finally:\n        conn.close()\n    return host\n\n\ndef remove(name):\n    conn = _db()\n    try:\n        with conn:\n            cur = conn.execute("DELETE FROM peer WHERE name = ?", (name,))\n        return cur.rowcount > 0\n    finally:\n        conn.close()\n\n\ndef listing(with_keys=False):\n    conn = _db()\n    try:\n        rows = conn.execute(\n            "SELECT name, host, key FROM peer ORDER BY name").fetchall()\n    finally:\n        conn.close()\n    # The key never goes to the browser: the page has no use for it, and a\n    # dashboard left open on a shared screen should not display the keys to\n    # every other machine you own.\n    return [{"name": r[0], "host": r[1],\n             **({"key": r[2]} if with_keys else {})} for r in rows]\n\n\ndef _one(name):\n    for peer in listing(with_keys=True):\n        if peer["name"] == name:\n            return peer\n    raise KeyError("no device called %r" % name)\n\n\ndef fetch(name, path, params):\n    """Ask a device for one API path."""\n    peer = _one(name)\n    flat = []\n    for key_name, values in params.items():\n        for value in values:\n            flat.append((key_name, value))\n    url = peer["host"] + path + ("?" + urlencode(flat) if flat else "")\n    request = urllib.request.Request(url, headers={share.HEADER: peer["key"]})\n    try:\n        with urllib.request.urlopen(request, timeout=TIMEOUT) as response:\n            return json.loads(response.read().decode())\n    except urllib.error.HTTPError as error:\n        detail = ""\n        try:\n            detail = json.loads(error.read().decode()).get("error", "")\n        except Exception:\n            pass\n        if error.code == 401:\n            raise RuntimeError("%s refused the key" % name)\n        if error.code == 429:\n            raise RuntimeError("%s is refusing keys for a moment" % name)\n        raise RuntimeError(detail or "%s answered %d" % (name, error.code))\n    except urllib.error.URLError as error:\n        reason = getattr(error, "reason", error)\n        # EHOSTUNREACH from inside an app bundle is almost never a routing\n        # problem: macOS refuses an app\'s local network access until it is\n        # allowed, and reports the refusal as "no route to host". The same\n        # request from a terminal succeeds, which is exactly what makes it\n        # baffling to diagnose from the message alone.\n        if getattr(reason, "errno", None) == 65 and _inside_app_bundle():\n            raise RuntimeError(\n                "macOS is blocking Procwatch from your local network, so it "\n                "cannot reach %s. Allow it in System Settings \\u203a Privacy & "\n                "Security \\u203a Local Network, then reopen Procwatch." % name)\n        raise RuntimeError(\n            "cannot reach %s. Is it awake, and is `procwatch share` running "\n            "there? (%s)" % (name, reason))\n    except ValueError:\n        raise RuntimeError("%s did not return data" % name)\n\n\ndef _inside_app_bundle():\n    """Whether this process was started by the menu bar app.\n\n    Only the app is subject to the local network prompt; the same code run\n    from a terminal inherits the terminal\'s permission and works.\n    """\n    import sys\n    entry = (sys.argv[0] if sys.argv else "") or ""\n    return ".app/Contents/" in os.path.abspath(entry)\n\n\ndef check(name):\n    """Whether a device answers, and what it is."""\n    try:\n        info = fetch(name, "/api/info", {})\n    except (RuntimeError, KeyError, OSError) as error:\n        return {"name": name, "ok": False, "error": str(error)[:200]}\n    # Against that machine\'s clock, not ours: two Macs can be hours apart in\n    # absolute time, which would report a healthy recorder as long stale.\n    age = None\n    if info.get("last_tick"):\n        reference = int(info.get("now") or time.time())\n        age = reference - int(info["last_tick"])\n    return {"name": name, "ok": True, "hostname": info.get("hostname", ""),\n            "chip": info.get("chip", ""), "cores": info.get("cores"),\n            "last_tick_age": age}\n')
_sampler = _install('sampler', '# procwatch/sampler.py\n"""One tick: read, difference, aggregate, select, write.\n\nCPU is a rate computed from cumulative-time deltas. It is never read from\n`ps %cpu`, which is a decaying average over an opaque window (`man ps`),\ndoes not reconcile against a system total, and cannot be integrated across\nbuckets -- which is exactly what the rollup arithmetic does.\n"""\nimport collections\n\nfrom . import config, identity\n\nAgg = collections.namedtuple(\n    "Agg", "cpu rss nproc cmdline net_in net_out disk_read disk_write energy stuck",\n    defaults=("", 0, 0, 0, 0, 0, 0))\n\n# A process that has burned a whole core for this many consecutive ticks while\n# reading and writing nothing at all is doing no work anything can observe.\n# macOS has no supported way to ask whether an app is servicing its run loop --\n# Activity Monitor uses a private interface -- so this is a heuristic and is\n# reported as "possibly stuck", never as fact.\nSTUCK_CPU = 95.0\nSTUCK_TICKS = 4\n\n\ndef cpu_percent(prev_cs, cur_cs, dt):\n    """Rate over a known interval, or None when the reading is unusable."""\n    if dt <= 0:\n        return None\n    delta_cs = cur_cs - prev_cs\n    if delta_cs < 0:\n        return None\n    return (delta_cs / 100.0) / dt * 100.0\n\n\ndef _delta(prev, cur):\n    """Difference two cumulative counters, discarding a counter that went\n    backwards -- which means the pid was recycled or the source reset."""\n    if prev is None or cur is None or cur < prev:\n        return 0\n    return cur - prev\n\n\ndef aggregate(procs, prev_state, now, dt, extra=None, prev_extra=None,\n              stuck_runs=None):\n    """Fold processes into per-identity totals; return them and the new state.\n\n    prev_state maps pid -> (start_time, cputime_cs) from the previous tick.\n    The returned state map covers every pid in `procs` regardless of whether\n    it had a usable previous reading -- callers rely on this to refresh\n    sampler_state even on a first-sighting or post-gap tick.\n\n    `extra` and `prev_extra` map pid -> (net_in, net_out, disk_read,\n    disk_write, energy) of CUMULATIVE counters, this tick and last. Like\n    cputime they are differenced, never read raw. A pid missing from either\n    contributes zero rather than dropping the process, since network and disk\n    coverage is partial by nature: nettop reports only processes that touched\n    the network, and libproc refuses other users\' processes.\n    """\n    extra = extra or {}\n    prev_extra = prev_extra or {}\n    stuck_runs = stuck_runs or {}\n    aggs = {}\n    state = {}\n    for proc in procs:\n        state[proc.pid] = (proc.start_time, proc.cputime_cs)\n        previous = prev_state.get(proc.pid)\n        if previous is None or previous[0] != proc.start_time:\n            continue  # unseen, or a recycled pid whose clock is not ours\n        cpu = cpu_percent(previous[1], proc.cputime_cs, dt)\n        if cpu is None:\n            continue\n\n        cur_x, prev_x = extra.get(proc.pid), prev_extra.get(proc.pid)\n        if cur_x and prev_x:\n            deltas = tuple(_delta(prev_x[i], cur_x[i]) for i in range(5))\n        else:\n            deltas = (0, 0, 0, 0, 0)\n        busy_idle = cpu >= STUCK_CPU and deltas[2] == 0 and deltas[3] == 0\n        stuck = 1 if busy_idle and stuck_runs.get(proc.pid, 0) + 1 >= STUCK_TICKS else 0\n\n        key = identity.derive(proc.comm, proc.command)\n        current = aggs.get(key)\n        if current is None:\n            aggs[key] = Agg(cpu, proc.rss_kb, 1, proc.command, *deltas, stuck)\n        else:\n            aggs[key] = Agg(current.cpu + cpu,\n                            current.rss + proc.rss_kb,\n                            current.nproc + 1,\n                            current.cmdline,\n                            current.net_in + deltas[0],\n                            current.net_out + deltas[1],\n                            current.disk_read + deltas[2],\n                            current.disk_write + deltas[3],\n                            current.energy + deltas[4],\n                            max(current.stuck, stuck))\n    return aggs, state\n\n\ndef _sum_field(rows, name):\n    return sum(getattr(a, name) for a in rows)\n\n\ndef select(aggs):\n    """Split into the recorded set and a single __other__ remainder.\n\n    Ranked by the union of top CPU, top memory, top network and top disk, so a\n    process that is quiet on CPU but saturating the network still gets its own\n    row instead of vanishing into the remainder.\n    """\n    keys = set()\n    for field in ("cpu", "rss", "net_in", "net_out", "disk_read", "disk_write"):\n        ranked = sorted(aggs, key=lambda k: getattr(aggs[k], field), reverse=True)\n        # Rank by a metric only where something actually used it. Otherwise a\n        # tick in which nothing touched the network still reserves TOP_N slots\n        # for "top network users", pulling in arbitrary processes and emptying\n        # the __other__ remainder that makes the chart reconcile.\n        ranked = [k for k in ranked[:config.TOP_N] if getattr(aggs[k], field) > 0]\n        keys |= set(ranked)\n    kept = {k: aggs[k] for k in keys}\n    rest = [aggs[k] for k in aggs if k not in keys]\n    other = Agg(_sum_field(rest, "cpu"), _sum_field(rest, "rss"),\n                _sum_field(rest, "nproc"), "",\n                _sum_field(rest, "net_in"), _sum_field(rest, "net_out"),\n                _sum_field(rest, "disk_read"), _sum_field(rest, "disk_write"),\n                _sum_field(rest, "energy"), 0)\n    return kept, other\n\n\ndef _proc_id(conn, exe, args_sig, cmdline_full, is_system=True, app=""):\n    """Intern an identity, recording whether it is part of macOS.\n\n    The flag is decided here because this is the only place the parent chain\n    is available -- a process that reports no path (postgres renames its\n    workers, autofsd exposes nothing) can only be resolved by looking at what\n    spawned it, and the history keeps no parent.\n    """\n    row = conn.execute(\n        "SELECT id, is_system, app FROM proc WHERE exe = ? AND args_sig = ?",\n        (exe, args_sig)).fetchone()\n    if row:\n        if app and not row[2]:\n            conn.execute("UPDATE proc SET app = ? WHERE id = ?", (app, row[0]))\n        # Correct a stored flag when this reading knows better. The backfill\n        # for pre-existing identities only had the command line, which is a\n        # bare name for anything that rewrote its own argv, so it had to leave\n        # those as macOS. Here the parent chain is available, so a "yours"\n        # verdict is better information and replaces it.\n        if row[1] and not is_system:\n            conn.execute("UPDATE proc SET is_system = 0 WHERE id = ?", (row[0],))\n        return row[0]\n    cur = conn.execute(\n        "INSERT INTO proc (exe, args_sig, cmdline_full, is_system, app) "\n        "VALUES (?,?,?,?,?)",\n        (exe, args_sig, cmdline_full, 1 if is_system else 0, app or ""))\n    return cur.lastrowid\n\n\ndef _load_state(conn):\n    """Only the newest tick\'s rows.\n\n    MAX(updated_ts) over the whole table can name a row left behind by a\n    process that exited, whose timestamp may even be in the future after a\n    backwards clock step. Taking dt from one tick and the cputime baseline\n    from another invents a spike.\n    """\n    rows = conn.execute(\n        "SELECT pid, start_time, cputime_cs FROM sampler_state "\n        "WHERE updated_ts = (SELECT MAX(updated_ts) FROM sampler_state)").fetchall()\n    return {r[0]: (r[1], r[2]) for r in rows}\n\n\ndef _last_tick(conn):\n    row = conn.execute("SELECT MAX(updated_ts) FROM sampler_state").fetchone()\n    return row[0]\n\n\ndef _save_state(conn, state, now):\n    conn.executemany(\n        "INSERT INTO sampler_state (pid, start_time, cputime_cs, updated_ts) "\n        "VALUES (?,?,?,?) ON CONFLICT(pid) DO UPDATE SET "\n        "start_time=excluded.start_time, cputime_cs=excluded.cputime_cs, "\n        "updated_ts=excluded.updated_ts",\n        [(pid, s[0], s[1], now) for pid, s in state.items()])\n    conn.execute("DELETE FROM sampler_state WHERE updated_ts < ?",\n                 (now - config.STATE_TTL,))\n\n\ndef _load_extra(conn):\n    """{pid: (net_in, net_out, disk_read, disk_write, energy)} from last tick."""\n    rows = conn.execute(\n        "SELECT pid, net_in, net_out, disk_read, disk_write, energy, stuck_run "\n        "FROM sampler_extra").fetchall()\n    return ({r[0]: tuple(r[1:6]) for r in rows},\n            {r[0]: r[6] for r in rows})\n\n\ndef _save_extra(conn, extra, aggs_stuck, now):\n    conn.executemany(\n        "INSERT INTO sampler_extra (pid, net_in, net_out, disk_read, disk_write, "\n        "energy, stuck_run, updated_ts) VALUES (?,?,?,?,?,?,?,?) "\n        "ON CONFLICT(pid) DO UPDATE SET net_in=excluded.net_in, "\n        "net_out=excluded.net_out, disk_read=excluded.disk_read, "\n        "disk_write=excluded.disk_write, energy=excluded.energy, "\n        "stuck_run=excluded.stuck_run, updated_ts=excluded.updated_ts",\n        [(pid, v[0], v[1], v[2], v[3], v[4], aggs_stuck.get(pid, 0), now)\n         for pid, v in extra.items()])\n    conn.execute("DELETE FROM sampler_extra WHERE updated_ts < ?",\n                 (now - config.STATE_TTL,))\n\n\ndef tick(conn, procs, readings, now, extra=None, batt=None,\n         system_pids=None, app_pids=None):\n    """Record one sample. Safe to call on an empty or a populated database.\n\n    aggregate()\'s state map is built solely from `procs` -- it does not\n    depend on prev_state or dt -- so one call produces both the correct\n    aggregates (empty when there is nothing to diff against) and the\n    correct state to persist, on the first tick, a post-gap tick, and a\n    normal tick alike.\n\n    `extra` is {pid: (net_in, net_out, disk_read, disk_write, energy)} of\n    cumulative counters gathered this tick. Omitting it records CPU and memory\n    only, which is what happens when nettop or libproc are unavailable.\n    """\n    extra = extra or {}\n    system_pids = system_pids or {}\n\n    # An identity is macOS only if every process under it is.\n    system_by_key, app_by_key = {}, {}\n    app_pids = app_pids or {}\n    for proc in procs:\n        key = identity.derive(proc.comm, proc.command)\n        flag = system_pids.get(proc.pid, True)\n        system_by_key[key] = system_by_key.get(key, True) and flag\n        if not app_by_key.get(key):\n            app_by_key[key] = app_pids.get(proc.pid) or ""\n\n    with conn:\n        previous_ts = _last_tick(conn)\n        prev_state = _load_state(conn)\n        prev_extra, stuck_runs = _load_extra(conn)\n        dt = None if previous_ts is None else now - previous_ts\n\n        if dt is not None and (dt < 0 or dt > config.INTERVAL * config.GAP_FACTOR):\n            reason = "clock" if dt < 0 else "sleep"\n            conn.execute(\n                "INSERT OR IGNORE INTO gap (ts_start, ts_end, reason) VALUES (?,?,?)",\n                (min(previous_ts, now), max(previous_ts, now), reason))\n            prev_state = {}   # the delta across a sleep or clock step is meaningless\n            prev_extra = {}\n\n        # dt only matters when prev_state is non-empty (a normal tick); on\n        # the first-ever tick prev_state is already {}. 0.0 makes cpu_percent\n        # return None unconditionally rather than relying on prev_state being\n        # empty to make the placeholder harmless.\n        aggs, state = aggregate(procs, prev_state, now,\n                                dt if dt is not None else 0.0,\n                                extra, prev_extra, stuck_runs)\n\n        # Carry the consecutive-busy-and-idle run forward per pid so the\n        # heuristic needs STUCK_TICKS in a row rather than one unlucky sample.\n        runs = {}\n        for proc in procs:\n            cur_x, prev_x = extra.get(proc.pid), prev_extra.get(proc.pid)\n            prev_cpu = prev_state.get(proc.pid)\n            if not (cur_x and prev_x and prev_cpu) or dt is None:\n                continue\n            cpu = cpu_percent(prev_cpu[1], proc.cputime_cs, dt)\n            quiet = (_delta(prev_x[2], cur_x[2]) == 0\n                     and _delta(prev_x[3], cur_x[3]) == 0)\n            if cpu is not None and cpu >= STUCK_CPU and quiet:\n                runs[proc.pid] = stuck_runs.get(proc.pid, 0) + 1\n\n        if aggs:\n            kept, other = select(aggs)\n            rows = []\n            for (exe, sig), agg in list(kept.items()) + [((config.OTHER, ""), other)]:\n                fallback = exe if sig == "" else exe + " " + sig\n                pid_row = _proc_id(conn, exe, sig, agg.cmdline or fallback,\n                                   system_by_key.get((exe, sig), True),\n                                   app_by_key.get((exe, sig), ""))\n                cpu = int(round(agg.cpu * 10))\n                rows.append((now, pid_row, cpu, cpu, now,\n                             agg.rss, agg.rss, agg.nproc, 1,\n                             agg.net_in, agg.net_out, agg.disk_read,\n                             agg.disk_write, agg.energy, agg.stuck))\n            conn.executemany(\n                "INSERT OR REPLACE INTO sample_raw (ts, proc_id, cpu_avg, cpu_max, "\n                "cpu_max_ts, rss_avg, rss_max, nproc, samples, net_in, net_out, "\n                "disk_read, disk_write, energy, stuck) "\n                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)\n            conn.execute(\n                "INSERT OR REPLACE INTO system_raw (ts, cpu_busy, load1, mem_used_kb, "\n                "mem_comp_kb, swap_used_kb, disk_free_kb, samples, expected, "\n                "batt_pct, batt_draw_mw, batt_full_mwh, on_ac) "\n                "VALUES (?,?,?,?,?,?,?,1,1,?,?,?,?)",\n                (now, int(round(sum(a.cpu for a in aggs.values()) * 10)),\n                 readings.load1, readings.mem_used_kb, readings.mem_comp_kb,\n                 readings.swap_used_kb, readings.disk_free_kb,\n                 (batt or {}).get("percent", -1) if batt else -1,\n                 (batt or {}).get("draw_mw") if (batt and batt.get("draw_mw")) else -1,\n                 (batt or {}).get("full_mwh", 0) or 0,\n                 1 if (batt or {}).get("on_ac", True) else 0))\n\n        _save_state(conn, state, now)\n        if extra:\n            _save_extra(conn, extra, runs, now)\n')
_rollup = _install('rollup', '"""Collapse expired buckets into the next coarser tier.\n\nTwo rules carry the whole design. cpu_max is the max of the source maxima, so\na four-minute spike still reads at its true height a year later. cpu_avg is\nweighted by each source row\'s sample count -- an average of averages is wrong\nwhenever buckets hold differing numbers of samples, which happens after every\nsleep.\n"""\nfrom . import config\n\n\ndef bucket_start(ts, seconds):\n    return ts - (ts % seconds)\n\n\ndef _tier_pairs():\n    return list(zip(config.TIERS, config.TIERS[1:]))\n\n\ndef collapse(conn, finer, coarser, now):\n    """Move rows older than finer.retain_seconds up a tier. Returns buckets written."""\n    cutoff = now - finer.retain_seconds\n    sample_src, sample_dst = "sample_" + finer.name, "sample_" + coarser.name\n    system_src, system_dst = "system_" + finer.name, "system_" + coarser.name\n\n    boundaries = [r[0] for r in conn.execute(\n        "SELECT DISTINCT ts / ? FROM (SELECT ts FROM %s WHERE ts < ? "\n        "UNION SELECT ts FROM %s WHERE ts < ?) ORDER BY 1 LIMIT ?"\n        % (sample_src, system_src),\n        (coarser.seconds, cutoff, cutoff, config.ROLLUP_BATCH)).fetchall()]\n    if not boundaries:\n        return 0\n\n    with conn:\n        for index in boundaries:\n            low = index * coarser.seconds\n            high = low + coarser.seconds\n            rows = conn.execute(\n                "SELECT proc_id, cpu_avg, cpu_max, cpu_max_ts, rss_avg, rss_max, "\n                "nproc, samples, net_in, net_out, disk_read, disk_write, "\n                "energy, stuck FROM %s WHERE ts >= ? AND ts < ?" % sample_src,\n                (low, high)).fetchall()\n\n            merged = {}\n            for (pid, cpu_avg, cpu_max, cpu_max_ts, rss_avg, rss_max, nproc, samples,\n                 net_in, net_out, disk_read, disk_write, energy, stuck) in rows:\n                acc = merged.get(pid)\n                if acc is None:\n                    # Byte and energy counters are TOTALS for the bucket, not rates,\n                    # so they add rather than average. stuck is a flag: a\n                    # bucket is suspect if any source bucket was.\n                    merged[pid] = [cpu_avg * samples, cpu_max, cpu_max_ts,\n                                   rss_avg * samples, rss_max, nproc, samples,\n                                   net_in, net_out, disk_read, disk_write,\n                                   energy, stuck]\n                    continue\n                acc[0] += cpu_avg * samples\n                if cpu_max > acc[1]:\n                    acc[1], acc[2] = cpu_max, cpu_max_ts\n                acc[3] += rss_avg * samples\n                acc[4] = max(acc[4], rss_max)\n                acc[5] = max(acc[5], nproc)\n                acc[6] += samples\n                acc[7] += net_in\n                acc[8] += net_out\n                acc[9] += disk_read\n                acc[10] += disk_write\n                acc[11] += energy\n                acc[12] = max(acc[12], stuck)\n\n            conn.executemany(\n                "INSERT INTO %s (ts, proc_id, cpu_avg, cpu_max, cpu_max_ts, rss_avg, "\n                "rss_max, nproc, samples, net_in, net_out, disk_read, "\n                "disk_write, energy, stuck) "\n                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) "\n                "ON CONFLICT(ts, proc_id) DO UPDATE SET "\n                "cpu_avg=excluded.cpu_avg, cpu_max=excluded.cpu_max, "\n                "cpu_max_ts=excluded.cpu_max_ts, rss_avg=excluded.rss_avg, "\n                "rss_max=excluded.rss_max, nproc=excluded.nproc, "\n                "samples=excluded.samples" % sample_dst,\n                [(low, pid, acc[0] // acc[6], acc[1], acc[2],\n                  acc[3] // acc[6], acc[4], acc[5], acc[6],\n                  acc[7], acc[8], acc[9], acc[10], acc[11], acc[12])\n                 for pid, acc in merged.items()])\n\n            sys_rows = conn.execute(\n                "SELECT cpu_busy, load1, mem_used_kb, mem_comp_kb, swap_used_kb, "\n                "disk_free_kb, samples FROM %s WHERE ts >= ? AND ts < ?" % system_src,\n                (low, high)).fetchall()\n            if sys_rows:\n                weight = sum(r[6] for r in sys_rows) or 1\n                conn.execute(\n                    "INSERT INTO %s (ts, cpu_busy, load1, mem_used_kb, mem_comp_kb, "\n                    "swap_used_kb, disk_free_kb, samples, expected) "\n                    "VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(ts) DO UPDATE SET "\n                    "cpu_busy=excluded.cpu_busy, load1=excluded.load1, "\n                    "mem_used_kb=excluded.mem_used_kb, mem_comp_kb=excluded.mem_comp_kb, "\n                    "swap_used_kb=excluded.swap_used_kb, "\n                    "disk_free_kb=excluded.disk_free_kb, samples=excluded.samples, "\n                    "expected=excluded.expected" % system_dst,\n                    (low,\n                     sum(r[0] * r[6] for r in sys_rows) // weight,\n                     sum(r[1] * r[6] for r in sys_rows) // weight,\n                     sum(r[2] * r[6] for r in sys_rows) // weight,\n                     sum(r[3] * r[6] for r in sys_rows) // weight,\n                     sum(r[4] * r[6] for r in sys_rows) // weight,\n                     min(r[5] for r in sys_rows),\n                     weight,\n                     coarser.seconds // config.INTERVAL))\n                conn.execute("DELETE FROM %s WHERE ts >= ? AND ts < ?" % system_src,\n                             (low, high))\n\n            conn.execute("DELETE FROM %s WHERE ts >= ? AND ts < ?" % sample_src,\n                         (low, high))\n    return len(boundaries)\n\n\ndef prune_tier(conn, tier, now):\n    """Drop anything past this tier\'s window. The last tier has none."""\n    if tier.retain_seconds is None:\n        return\n    cutoff = now - tier.retain_seconds\n    with conn:\n        conn.execute("DELETE FROM sample_%s WHERE ts < ?" % tier.name, (cutoff,))\n        conn.execute("DELETE FROM system_%s WHERE ts < ?" % tier.name, (cutoff,))\n\n\ndef prune(conn, now):\n    for tier in config.TIERS:\n        prune_tier(conn, tier, now)\n\n\ndef run(conn, now):\n    for finer, coarser in _tier_pairs():\n        moved = collapse(conn, finer, coarser, now)\n        if moved < config.ROLLUP_BATCH:\n            # A partial batch means this tier\'s backlog just fully drained --\n            # safe to prune, and safe to keep rolling the next pair upward.\n            prune_tier(conn, finer, now)\n        else:\n            # A full batch means this tier still has a backlog. Rolling the\n            # tier above now would hand it a coarser bucket whose sources are\n            # only half present, and the next tick\'s upsert would overwrite\n            # rather than merge -- erasing whatever the first pass recorded.\n            break\n\n\ndef disk_guard(conn, now, free_bytes):\n    """Below the floor, coarsen early rather than delete.\n\n    Deleting a tier\'s rows outright destroys history that never reached any\n    coarser resolution, and because each tier\'s halved window is more\n    aggressive than its own collapse threshold, sustained pressure starves\n    coarse and archive of everything. Collapsing instead compacts ten raw\n    rows into one fine row -- more space freed, and only resolution is lost.\n\n    This tool exists because background processes quietly consumed a\n    machine. It will not be the process that fills a nearly-full disk, and\n    it will not be the process that silently erases the record either.\n    """\n    if free_bytes >= config.MIN_FREE_BYTES:\n        return False\n    for finer, coarser in _tier_pairs():\n        if finer.retain_seconds is None:\n            continue\n        # Treat rows as older than they are, halving the tier\'s effective\n        # window so its data moves up instead of being deleted.\n        early = now + finer.retain_seconds // 2\n        while collapse(conn, finer, coarser, early) == config.ROLLUP_BATCH:\n            pass\n    return True\n')
_procs = _install('procs', '"""Live process tree and the one mutating operation in the tool: signalling.\n\nEverything else procwatch does is read-only and historical. This module is\nwhat turns "that process has been eating a core for an hour" into something\nyou can act on, so it is deliberately the narrowest surface in the codebase:\none listing function and one signal function, both refusing anything the\ncalling user does not own.\n"""\nimport os\nimport signal as signal_module\nimport subprocess\n\nfrom . import identity, netstat, rusage\n\n# TERM asks, KILL compels. Nothing else is exposed: the point is to stop a\n# runaway process, not to offer a general signal console.\nALLOWED_SIGNALS = {"TERM": signal_module.SIGTERM, "KILL": signal_module.SIGKILL}\n\nPS_FIELDS = ["ps", "-Axo", "pid,ppid,uid,pcpu,rss,state,lstart,comm"]\n\n\ndef _own_uid():\n    return os.getuid()\n\n\ndef live_tree():\n    """Every process this user owns, grouped by application.\n\n    Grouping is by the same identity rule the recorder uses, so what appears\n    here as one row is the same thing that appears as one series in the\n    history -- 27 renderers of a browser are one entry with a child count,\n    not 27 rows that push everything else off the screen.\n\n    The parent chain is carried so a helper can be attributed to the app that\n    spawned it: a browser\'s renderers name the browser, not launchd.\n    """\n    out = subprocess.run(["ps", "-Axo", "pid,ppid,uid,pcpu,rss,state,comm"],\n                         capture_output=True, text=True, timeout=20)\n    if out.returncode != 0:\n        return {"groups": [], "error": "ps failed"}\n    commands = {}\n    cmd_out = subprocess.run(["ps", "-Axo", "pid,command"],\n                             capture_output=True, text=True, timeout=20)\n    for line in cmd_out.stdout.splitlines()[1:]:\n        pid_text, _, rest = line.strip().partition(" ")\n        if pid_text.isdigit():\n            commands[int(pid_text)] = rest.strip()\n\n    uid = _own_uid()\n    rows, parents = [], {}\n    for line in out.stdout.splitlines()[1:]:\n        parts = line.split(None, 6)\n        if len(parts) < 7 or not parts[0].isdigit():\n            continue\n        pid, ppid, puid = int(parts[0]), int(parts[1]), int(parts[2])\n        parents[pid] = ppid\n        if puid != uid:\n            continue\n        comm = parts[6].strip()\n        rows.append({"pid": pid, "ppid": ppid, "cpu": float(parts[3]),\n                     "rss_kb": int(parts[4]), "state": parts[5],\n                     "comm": comm, "command": commands.get(pid, comm)})\n\n    counters = rusage.read_all([r["pid"] for r in rows])\n    net = netstat.read()\n    ports = {}\n    for row in netstat.listeners():\n        ports.setdefault(row["pid"], []).append(row["port"])\n\n    groups = {}\n    for row in rows:\n        exe, sig = identity.derive(row["comm"], row["command"])\n        entry = groups.setdefault((exe, sig), {\n            "exe": exe, "args": sig, "command": row["command"],\n            "is_system": identity.is_system(row["comm"]),\n            "cpu": 0.0, "rss_kb": 0, "pids": [], "ports": [],\n            "disk_read": 0, "disk_write": 0, "net_in": 0, "net_out": 0,\n            "energy": 0, "waiting": 0})\n        entry["cpu"] += row["cpu"]\n        entry["rss_kb"] += row["rss_kb"]\n        entry["pids"].append(row["pid"])\n        entry["ports"].extend(ports.get(row["pid"], []))\n        # \'U\' is an uninterruptible wait -- blocked in the kernel, usually on\n        # I/O. It is the closest public signal to "not responding", and is\n        # reported as a count rather than a verdict.\n        if row["state"].startswith("U"):\n            entry["waiting"] += 1\n        counter = counters.get(row["pid"])\n        if counter:\n            entry["disk_read"] += counter[0]\n            entry["disk_write"] += counter[1]\n            entry["energy"] += counter[4]\n        seen = net.get(row["pid"])\n        if seen:\n            entry["net_in"] += seen[0]\n            entry["net_out"] += seen[1]\n\n    listing = []\n    for entry in groups.values():\n        entry["nproc"] = len(entry["pids"])\n        entry["ports"] = sorted(set(entry["ports"]))\n        # The lowest pid in a group is the one whose parent is outside it --\n        # the app itself rather than one of its helpers -- so it is the pid a\n        # "quit" should be aimed at.\n        entry["lead_pid"] = min(entry["pids"])\n        listing.append(entry)\n    listing.sort(key=lambda e: e["cpu"], reverse=True)\n    return {"groups": listing, "uid": uid}\n\n\ndef signal_pid(pid, name="TERM"):\n    """Send TERM or KILL to one process this user owns.\n\n    Refuses another user\'s process rather than letting the kernel refuse it,\n    so the caller gets an explanation instead of an errno, and refuses pid 1\n    outright -- signalling launchd is never what anyone meant.\n    """\n    if name not in ALLOWED_SIGNALS:\n        return {"ok": False, "error": "signal must be TERM or KILL"}\n    if pid <= 1:\n        return {"ok": False, "error": "refusing to signal pid %d" % pid}\n    try:\n        stat = subprocess.run(["ps", "-o", "uid=,comm=", "-p", str(pid)],\n                              capture_output=True, text=True, timeout=10)\n    except (OSError, subprocess.TimeoutExpired):\n        return {"ok": False, "error": "could not look up pid %d" % pid}\n    if stat.returncode != 0 or not stat.stdout.strip():\n        return {"ok": False, "error": "no such process: %d" % pid}\n    parts = stat.stdout.split(None, 1)\n    if int(parts[0]) != _own_uid():\n        return {"ok": False,\n                "error": "pid %d belongs to another user" % pid}\n    comm = (parts[1].strip() if len(parts) > 1 else "").split("/")[-1]\n    try:\n        os.kill(pid, ALLOWED_SIGNALS[name])\n    except ProcessLookupError:\n        return {"ok": False, "error": "process %d already gone" % pid}\n    except PermissionError:\n        return {"ok": False, "error": "not permitted to signal %d" % pid}\n    return {"ok": True, "pid": pid, "signal": name, "comm": comm}\n\n\ndef signal_group(pids, name="TERM"):\n    """Signal every pid in a group, reporting each outcome separately.\n\n    A partial failure is normal -- helpers exit on their own once the parent\n    goes -- so this never aborts on the first error.\n    """\n    return [signal_pid(pid, name) for pid in pids]\n')
_live = _install('live', '"""Instantaneous readings for the live view, taken without writing anything.\n\nThe recorder samples every 30 seconds because that is the cadence worth\nkeeping for years. Watching a machine wants something faster, and the two\nneeds do not have to share a mechanism: this takes its own reading, diffs it\nagainst its own in-memory baseline, and returns. Nothing here touches the\ndatabase, so the live view can update every couple of seconds without\ninflating the history or fighting the sampler for the write lock.\n\n`ps` plus libproc costs about 70 ms, which is affordable at that rate.\n`nettop` costs five seconds, which is not, so network figures come from a\nbackground refresh and are served slightly stale rather than holding up\nevery request.\n"""\nimport threading\nimport time\n\nfrom . import identity, netstat, psreader, rusage, system\n\n# Below this the deltas are dominated by sampling jitter rather than real\n# work, so the previous answer is reused instead of computing noise.\nMIN_INTERVAL = 0.4\n\n_lock = threading.Lock()\n_prev = {"ts": None, "cpu": {}, "counters": {}}\n_net = {"ts": 0, "data": {}}\n_net_thread = None\n\n\ndef _refresh_network():\n    """nettop in the background, forever. Five seconds per pass, so the live\n    view gets numbers a few seconds old rather than waiting on them."""\n    while True:\n        try:\n            data = netstat.read()\n            with _lock:\n                _net["data"] = data\n                _net["ts"] = time.time()\n        except Exception:\n            pass\n        time.sleep(20)\n\n\ndef start_network_refresh():\n    global _net_thread\n    if _net_thread is None:\n        _net_thread = threading.Thread(target=_refresh_network, daemon=True)\n        _net_thread.start()\n\n\ndef snapshot():\n    """Current per-application rates, grouped the way the history groups them.\n\n    The first call establishes a baseline and reports zero rates -- there is\n    nothing to difference against yet. Every call after that is a real rate\n    over the actual elapsed interval, which is why the interval is returned:\n    a caller polling irregularly should know what window it is looking at.\n    """\n    now = time.time()\n    procs = psreader.read()\n    counters = rusage.read_all([p.pid for p in procs])\n    system_pids = identity.classify(procs)\n    app_pids = identity.apps(procs)\n\n    with _lock:\n        prev_ts = _prev["ts"]\n        prev_cpu = _prev["cpu"]\n        prev_counters = _prev["counters"]\n        net = dict(_net["data"])\n        net_age = now - _net["ts"] if _net["ts"] else None\n\n    dt = (now - prev_ts) if prev_ts else 0.0\n    usable = dt >= MIN_INTERVAL\n\n    ports = {}\n    for row in netstat.listeners():\n        ports.setdefault(row["pid"], []).append(row["port"])\n\n    groups = {}\n    cpu_state, counter_state = {}, {}\n    for proc in procs:\n        cpu_state[proc.pid] = (proc.start_time, proc.cputime_cs)\n        counter_state[proc.pid] = counters.get(proc.pid)\n\n        cpu = 0.0\n        was = prev_cpu.get(proc.pid)\n        if usable and was and was[0] == proc.start_time:\n            delta_cs = proc.cputime_cs - was[1]\n            if delta_cs >= 0:\n                cpu = (delta_cs / 100.0) / dt * 100.0\n\n        cur, old = counters.get(proc.pid), prev_counters.get(proc.pid)\n        read_rate = write_rate = 0.0\n        if usable and cur and old:\n            read_rate = max(0, cur[0] - old[0]) / dt\n            write_rate = max(0, cur[1] - old[1]) / dt\n\n        exe, sig = identity.derive(proc.comm, proc.command)\n        entry = groups.setdefault((exe, sig), {\n            "exe": exe, "args": sig, "command": proc.command,\n            "is_system": system_pids.get(proc.pid, True),\n            "app": app_pids.get(proc.pid) or "",\n            "cpu": 0.0, "rss_kb": 0, "pids": [], "ports": [],\n            "disk_read": 0.0, "disk_write": 0.0,\n            "net_in": 0, "net_out": 0, "energy": 0, "waiting": 0})\n        entry["is_system"] = entry["is_system"] and system_pids.get(proc.pid, True)\n        if not entry["app"]:\n            entry["app"] = app_pids.get(proc.pid) or ""\n        entry["cpu"] += cpu\n        entry["rss_kb"] += proc.rss_kb\n        entry["pids"].append(proc.pid)\n        entry["ports"].extend(ports.get(proc.pid, []))\n        entry["disk_read"] += read_rate\n        entry["disk_write"] += write_rate\n        if cur:\n            entry["energy"] += cur[4]\n        seen = net.get(proc.pid)\n        if seen:\n            entry["net_in"] += seen[0]\n            entry["net_out"] += seen[1]\n\n    with _lock:\n        _prev["ts"] = now\n        _prev["cpu"] = cpu_state\n        _prev["counters"] = counter_state\n\n    listing = []\n    for entry in groups.values():\n        entry["nproc"] = len(entry["pids"])\n        entry["ports"] = sorted(set(entry["ports"]))\n        entry["lead_pid"] = min(entry["pids"])\n        listing.append(entry)\n    listing.sort(key=lambda e: e["cpu"], reverse=True)\n\n    readings = system.read()\n    batt = system.battery()\n    return {\n        "ts": int(now),\n        "interval": round(dt, 2),\n        "warming_up": not usable,\n        "groups": listing,\n        "network_age": round(net_age, 1) if net_age is not None else None,\n        "system": {\n            "cpu_busy": sum(e["cpu"] for e in listing),\n            "load1": readings.load1 / 100.0,\n            "mem_used_kb": readings.mem_used_kb,\n            "mem_comp_kb": readings.mem_comp_kb,\n            "swap_used_kb": readings.swap_used_kb,\n            "disk_free_kb": readings.disk_free_kb,\n        },\n        "battery": batt,\n    }\n')
_query = _install('query', '"""Read side. Shapes the JSON the dashboard consumes: avg and max both\nsurfaced (with the timestamp of the max, so a coarse bucket can still name\nthe minute a spike happened), percentages unscaled from their stored\ninteger-tenths form, the synthetic __other__ row flagged rather than hidden,\nand a coverage ratio per system point so a mostly-asleep bucket reads\ndifferently from a genuinely idle one.\n\nTiers are DISJOINT IN TIME, not nested: a row lives in exactly one tier and\nonly moves to the next when it expires out of the one below (see rollup.py).\nraw holds roughly the last week, fine the month before that, and so on. A\nrequested window can straddle that boundary -- "last 24 hours" started\nentirely in raw, but as raw\'s retention window slides it will eventually\ndraw from fine too. Picking a single tier by span width alone (as if wider\nwindows just meant coarser copies of the same data) returns nothing for any\nwindow that falls outside whichever tier happens to hold data right now.\nSo every read here queries every tier that overlaps [start, end) and folds\nwhat comes back into uniform render buckets, using the same merge rules\nrollup.collapse uses when moving a bucket up a tier -- the read path must\nnot contradict the storage path.\n"""\nfrom . import config\n\n# A window wider than this many buckets is too dense to render usefully.\nTARGET_BUCKETS = 400\n\n_TIER_NAMES = frozenset(tier.name for tier in config.TIERS)\n_TIER_SECONDS = {tier.name: tier.seconds for tier in config.TIERS}\n\n\ndef pick_tier(span_seconds):\n    """The render resolution for this span: the finest tier whose bucket\n    count fits TARGET_BUCKETS. This only picks a bucket WIDTH to fold into --\n    it no longer selects which table gets read; every tier overlapping the\n    window is always read (see module docstring).\n    """\n    for tier in config.TIERS:\n        if span_seconds / float(tier.seconds) <= TARGET_BUCKETS:\n            return tier\n    return config.TIERS[-1]\n\n\ndef _bucket_start(ts, seconds):\n    return ts - (ts % seconds)\n\n\ndef _tier_union(prefix, select_cols, where_extra=""):\n    """A UNION ALL of `select_cols` across every tier\'s <prefix><name> table,\n    each filtered by ts BETWEEN a start/end placeholder pair. Safe against\n    double-counting because the tiers are disjoint in time (see module\n    docstring) -- a row read from one tier\'s table cannot also appear in\n    another\'s.\n    """\n    parts = ["SELECT %s FROM %s%s WHERE ts >= ? AND ts < ?%s"\n             % (select_cols, prefix, tier.name, where_extra) for tier in config.TIERS]\n    return " UNION ALL ".join(parts)\n\n\ndef _proc_names(conn, ids):\n    placeholders = ",".join("?" * len(ids))\n    return {r[0]: (r[1], r[2], bool(r[3]), r[4] or "") for r in conn.execute(\n        "SELECT id, exe, cmdline_full, is_system, app FROM proc WHERE id IN (%s)"\n        % placeholders, ids).fetchall()}\n\n\n# A synthetic identity for the folded remainder, distinct from any real\n# proc.id (which are positive).\n_OTHER_ID = -1\n\n\ndef _fold_samples(rows, names, bucket_width):\n    """Merge rows (proc_id, ts, cpu_avg, cpu_max, cpu_max_ts, rss_avg,\n    rss_max, nproc, samples) landing in the same (proc_id, render bucket)\n    into one point per process per bucket, then group into per-process\n    entries. `rows` must be ordered by ts ascending so a tie in cpu_max\n    keeps the earliest timestamp, matching rollup.collapse\'s own\n    strictly-greater comparison.\n    """\n    acc = {}\n    for (pid, ts, cpu_avg, cpu_max, cpu_max_ts, rss_avg, rss_max, nproc, samples,\n         net_in, net_out, disk_read, disk_write, energy, stuck) in rows:\n        key = (pid, _bucket_start(ts, bucket_width))\n        a = acc.get(key)\n        if a is None:\n            acc[key] = {"cpu_avg_sum": cpu_avg * samples, "cpu_max": cpu_max,\n                        "cpu_max_ts": cpu_max_ts, "rss_avg_sum": rss_avg * samples,\n                        "rss_max": rss_max, "nproc": nproc, "samples": samples,\n                        # Byte and energy counters are totals for the interval,\n                        # not rates, so they add. Rates are derived at render\n                        # time by dividing by the bucket\'s own width.\n                        "net_in": net_in, "net_out": net_out,\n                        "disk_read": disk_read, "disk_write": disk_write,\n                        "energy": energy, "stuck": stuck}\n            continue\n        a["cpu_avg_sum"] += cpu_avg * samples\n        if cpu_max > a["cpu_max"]:\n            a["cpu_max"], a["cpu_max_ts"] = cpu_max, cpu_max_ts\n        a["rss_avg_sum"] += rss_avg * samples\n        a["rss_max"] = max(a["rss_max"], rss_max)\n        a["nproc"] = max(a["nproc"], nproc)\n        a["samples"] += samples\n        a["net_in"] += net_in\n        a["net_out"] += net_out\n        a["disk_read"] += disk_read\n        a["disk_write"] += disk_write\n        a["energy"] += energy\n        a["stuck"] = max(a["stuck"], stuck)\n\n    grouped = {}\n    for (pid, bucket_ts), a in sorted(acc.items(), key=lambda kv: kv[0][1]):\n        exe, cmdline, is_system, app = names[pid]\n        entry = grouped.setdefault(pid, {\n            "exe": exe, "cmdline": cmdline, "is_other": exe == config.OTHER,\n            "is_system": is_system, "app": app, "points": []})\n        entry["points"].append({\n            "ts": bucket_ts,\n            "cpu_avg": (a["cpu_avg_sum"] / a["samples"]) / 10.0,\n            "cpu_max": a["cpu_max"] / 10.0,\n            "cpu_max_ts": a["cpu_max_ts"],\n            "rss_avg": a["rss_avg_sum"] / a["samples"],\n            "rss_max": a["rss_max"],\n            "nproc": a["nproc"],\n            "net_in": a["net_in"], "net_out": a["net_out"],\n            "disk_read": a["disk_read"], "disk_write": a["disk_write"],\n            "energy": a["energy"], "stuck": a["stuck"]})\n    return grouped\n\n\ndef _fold_system(rows, bucket_width, now=None):\n    """Same idea as _fold_samples for system_<tier> rows: cpu_busy, load1,\n    mem_used_kb, mem_comp_kb and swap_used_kb are sample-weighted, disk_free_kb\n    is a true min.\n\n    `expected` is NOT accumulated from the source rows. It is the nominal count\n    a bucket of this width implies -- `bucket_width // INTERVAL` -- which is what\n    `rollup.collapse` writes when it materialises a bucket. Summing the sources\n    instead would make coverage the ratio of present samples to *present*\n    expectation, which is 1.0 by construction: a five-minute bucket holding two\n    ticks of a possible ten would read fully covered, exactly the mostly-asleep\n    case the sub-0.5 hatching exists to reveal. It would also make the same\n    window change appearance the night rollup crossed it, because the fold and\n    the stored row would disagree.\n\n    The bucket containing `now` is prorated to the wall clock actually elapsed\n    within it, so a window ending mid-bucket does not read as a gap merely for\n    not having happened yet.\n    """\n    nominal = max(1, bucket_width // config.INTERVAL)\n    acc = {}\n    for (ts, cpu_busy, load1, mem_used, mem_comp, swap_used, disk_free, samples,\n         expected, batt_pct, batt_draw_mw, batt_full_mwh, on_ac) in rows:\n        key = _bucket_start(ts, bucket_width)\n        a = acc.get(key)\n        if a is None:\n            acc[key] = {"cpu_busy_sum": cpu_busy * samples, "load1_sum": load1 * samples,\n                        "mem_used_sum": mem_used * samples, "mem_comp_sum": mem_comp * samples,\n                        "swap_used_sum": swap_used * samples, "disk_free": disk_free,\n                        "samples": samples, "batt_pct": batt_pct,\n                        "draw_mw": batt_draw_mw, "full_mwh": batt_full_mwh,\n                        "on_ac": on_ac}\n            continue\n        a["cpu_busy_sum"] += cpu_busy * samples\n        a["load1_sum"] += load1 * samples\n        a["mem_used_sum"] += mem_used * samples\n        a["mem_comp_sum"] += mem_comp * samples\n        a["swap_used_sum"] += swap_used * samples\n        a["disk_free"] = min(a["disk_free"], disk_free)\n        a["samples"] += samples\n        if batt_pct >= 0:\n            a["batt_pct"] = batt_pct\n        if batt_draw_mw > 0:\n            a["draw_mw"] = max(a["draw_mw"], batt_draw_mw)\n        a["full_mwh"] = max(a["full_mwh"], batt_full_mwh)\n        a["on_ac"] = min(a["on_ac"], on_ac)\n\n    result = []\n    for ts in sorted(acc):\n        a = acc[ts]\n        weight = a["samples"] or 1\n        expected = nominal\n        if now is not None and ts <= now < ts + bucket_width:\n            elapsed = max(config.INTERVAL, now - ts)\n            expected = max(1, min(nominal, elapsed // config.INTERVAL))\n        result.append({\n            "ts": ts,\n            "cpu_busy": (a["cpu_busy_sum"] / weight) / 10.0,\n            "load1": (a["load1_sum"] / weight) / 100.0,\n            "mem_used_kb": a["mem_used_sum"] // weight,\n            "mem_comp_kb": a["mem_comp_sum"] // weight,\n            "swap_used_kb": a["swap_used_sum"] // weight,\n            "disk_free_kb": a["disk_free"],\n            "expected": expected,\n            "samples": a["samples"],\n            "batt_pct": a["batt_pct"],\n            "batt_draw_mw": a["draw_mw"],\n            "batt_full_mwh": a["full_mwh"],\n            "on_ac": bool(a["on_ac"]),\n            "coverage": min(1.0, a["samples"] / float(expected))})\n    return result\n\n\ndef series(conn, start, end, limit=12, scope="all"):\n    """Top-`limit` series by peak CPU in [start, end), plus system and gaps.\n\n    scope="apps" ranks and returns APPLICATIONS: identities that belong to a\n    .app bundle, folded together under the bundle\'s name. Ranking has to\n    happen inside the scope, not before it -- taking the top twelve processes\n    overall and then discarding the ones that are not applications returns\n    nothing at all on a machine whose heaviest consumers are Spotlight and\n    media analysis, which is most machines over a long enough window.\n    """\n    tier = pick_tier(max(end - start, 1))\n    bucket_width = tier.seconds\n\n    scope_filter = ""\n    if scope == "apps":\n        scope_filter = (" AND proc_id IN (SELECT id FROM proc WHERE app != \'\')")\n    # The sampler\'s own remainder row never competes for a rank: it is folded\n    # into the remainder computed below, so there is exactly one of them.\n    rank_filter = scope_filter + (\n        " AND proc_id NOT IN (SELECT id FROM proc WHERE exe = \'%s\')" % config.OTHER)\n    rank_sql = ("SELECT proc_id, MAX(cpu_max) FROM (%s) GROUP BY proc_id "\n                "ORDER BY 2 DESC LIMIT ?"\n                % _tier_union("sample_", "proc_id, cpu_max", rank_filter))\n    rank_params = []\n    for _ in config.TIERS:\n        rank_params.extend([start, end])\n    rank_params.append(limit)\n    ids = [r[0] for r in conn.execute(rank_sql, rank_params).fetchall()]\n\n    # A window with no process samples (a sleep gap, or before any process\n    # existed) is still a window that can carry system and gap rows -- those\n    # are queried below regardless of whether any process ranked here.\n    grouped = {}\n    if ids:\n        placeholders = ",".join("?" * len(ids))\n        detail_cols = ("proc_id, ts, cpu_avg, cpu_max, cpu_max_ts, rss_avg, "\n                       "rss_max, nproc, samples, net_in, net_out, disk_read, "\n                       "disk_write, energy, stuck")\n        detail_sql = ("SELECT %s FROM (%s) ORDER BY ts"\n                       % (detail_cols,\n                          _tier_union("sample_", detail_cols,\n                                      " AND proc_id IN (%s)" % placeholders)))\n        detail_params = []\n        for _ in config.TIERS:\n            detail_params.extend([start, end] + ids)\n        rows = conn.execute(detail_sql, detail_params).fetchall()\n        grouped = _fold_samples(rows, _proc_names(conn, ids), bucket_width)\n\n    # Everything that did not make the cut, as one band.\n    #\n    # Without this the chart was a stack of the top `limit` processes and\n    # nothing else: the sampler keeps forty per tick, so ranks thirteen to\n    # forty were simply absent. The stack therefore did not add up to the\n    # machine -- measured against the recorded system total it came to about\n    # half -- and the energy chart, which normalises by the sum of what it was\n    # given, reported shares of a subset as though they were shares of the\n    # whole.\n    #\n    # Summed per timestamp in SQL first, so folding into render buckets is\n    # then the ordinary time-fold rather than a sum across processes that\n    # _fold_samples would have averaged.\n    rest_filter = scope_filter\n    rest_params_extra = []\n    if ids:\n        rest_filter += " AND proc_id NOT IN (%s)" % ",".join("?" * len(ids))\n        rest_params_extra = ids\n    rest_cols = ("ts, cpu_avg, cpu_max, cpu_max_ts, rss_avg, rss_max, nproc, "\n                 "samples, net_in, net_out, disk_read, disk_write, energy, stuck")\n    rest_sql = (\n        "SELECT ts, SUM(cpu_avg), SUM(cpu_avg), MIN(ts), SUM(rss_avg), "\n        "SUM(rss_max), SUM(nproc), MAX(samples), SUM(net_in), SUM(net_out), "\n        "SUM(disk_read), SUM(disk_write), SUM(energy), MAX(stuck) "\n        "FROM (%s) GROUP BY ts ORDER BY ts"\n        % _tier_union("sample_", rest_cols, rest_filter))\n    rest_params = []\n    for _ in config.TIERS:\n        rest_params.extend([start, end] + rest_params_extra)\n    rest_rows = conn.execute(rest_sql, rest_params).fetchall()\n    # cpu_max is reported as the sum of averages rather than a real maximum:\n    # the peaks of a hundred unrelated processes did not happen at the same\n    # instant, so any larger figure would be a number nothing ever reached.\n    rest_rows = [(_OTHER_ID,) + tuple(r) for r in rest_rows if r[1]]\n    if rest_rows:\n        names = {_OTHER_ID: (config.OTHER, "", 1, "")}\n        for pid, points in _fold_samples(rest_rows, names, bucket_width).items():\n            grouped[pid] = points\n\n    sys_cols = ("ts, cpu_busy, load1, mem_used_kb, mem_comp_kb, swap_used_kb, "\n                "disk_free_kb, samples, expected, batt_pct, batt_draw_mw, "\n                "batt_full_mwh, on_ac")\n    system_sql = ("SELECT %s FROM (%s) ORDER BY ts"\n                   % (sys_cols, _tier_union("system_", sys_cols)))\n    system_params = []\n    for _ in config.TIERS:\n        system_params.extend([start, end])\n    system_rows = conn.execute(system_sql, system_params).fetchall()\n    system = _fold_system(system_rows, bucket_width, now=end)\n\n    # ts_start <= ts_end always holds (db.py normalises backwards clock steps);\n    # reason (\'sleep\' or \'clock\') is passed through so the client can render\n    # a clock rewind -- overwritten wall-clock time -- differently from a\n    # genuine absence of data.\n    gaps = [{"start": r[0], "end": r[1], "reason": r[2]} for r in conn.execute(\n        "SELECT ts_start, ts_end, reason FROM gap WHERE ts_end >= ? AND ts_start < ? "\n        "ORDER BY ts_start", (start, end)).fetchall()]\n\n    # Ranked first, remainder last: the caller stacks smallest-first but reads\n    # this order for colour, and the remainder is not a process competing for\n    # a rank.\n    order = [i for i in ids if i in grouped]\n    if _OTHER_ID in grouped:\n        order.append(_OTHER_ID)\n    return {"tier": tier.name, "series": [grouped[i] for i in order],\n            "system": system, "gaps": gaps}\n\n\ndef bucket_detail(conn, tier_name, ts):\n    """Every process recorded in one render bucket, ranked by average CPU.\n\n    tier_name can come from an HTTP query parameter, so it is checked\n    against the known tiers before being interpolated into SQL. ts is\n    floored to that tier\'s bucket width and every source tier overlapping\n    [bucket_start, bucket_start + width) is read and folded -- the bucket a\n    client is drilling into may already straddle a tier boundary, the same\n    reason series() cannot read a single table either.\n    """\n    if tier_name not in _TIER_NAMES:\n        raise ValueError("unknown tier: %r" % (tier_name,))\n    width = _TIER_SECONDS[tier_name]\n    start = _bucket_start(ts, width)\n    end = start + width\n\n    sql = ("SELECT proc_id, ts, cpu_avg, cpu_max, cpu_max_ts, rss_avg, rss_max, "\n           "nproc, samples, net_in, net_out, disk_read, disk_write, energy, "\n           "stuck FROM (%s) ORDER BY ts"\n           % _tier_union("sample_", "proc_id, ts, cpu_avg, cpu_max, cpu_max_ts, "\n                         "rss_avg, rss_max, nproc, samples, net_in, net_out, "\n                         "disk_read, disk_write, energy, stuck"))\n    params = []\n    for _ in config.TIERS:\n        params.extend([start, end])\n    rows = conn.execute(sql, params).fetchall()\n    if not rows:\n        return []\n\n    ids = sorted(set(r[0] for r in rows))\n    grouped = _fold_samples(rows, _proc_names(conn, ids), width)\n\n    out = []\n    for entry in grouped.values():\n        point = entry["points"][0]  # one process, one bucket -> exactly one point\n        # cpu_max_ts travels with cpu_max. Drilling into a six-hour archive\n        # bucket is precisely when "which minute did it peak" is the question\n        # being asked, so dropping it here would defeat the tier design at the\n        # one place it pays off most.\n        out.append({"exe": entry["exe"], "cmdline": entry["cmdline"],\n                     "is_other": entry["is_other"],\n                     "is_system": entry.get("is_system", True),\n                     # Needed to fold helpers under the application that owns\n                     # them, the same way the charts group them.\n                     "app": entry.get("app", ""),\n                     "cpu_avg": point["cpu_avg"],\n                     "cpu_max": point["cpu_max"], "cpu_max_ts": point["cpu_max_ts"],\n                     "rss_kb": point["rss_avg"], "rss_max_kb": point["rss_max"],\n                     "nproc": point["nproc"], "net_in": point["net_in"],\n                     "net_out": point["net_out"], "disk_read": point["disk_read"],\n                     "disk_write": point["disk_write"], "energy": point["energy"],\n                     "stuck": point["stuck"]})\n    out.sort(key=lambda r: r["cpu_avg"], reverse=True)\n    return out\n\n\ndef activity(conn, start, end):\n    """Machine busyness per hour, for the calendar heatmap.\n\n    Deliberately its own query rather than a coarse `series` call: the\n    heatmap wants one number per wall-clock hour across weeks, which is a\n    different shape from "top processes over a window" and would otherwise\n    pull every per-process row in the range across the wire to be thrown\n    away.\n\n    Reads every tier, since a month-long span straddles them, and reports\n    coverage per hour so an hour the machine was asleep renders as absent\n    rather than as idle -- those are not the same thing and the whole point\n    of the grid is spotting the difference.\n    """\n    sql = ("SELECT ts, cpu_busy, samples, expected FROM (%s) ORDER BY ts"\n           % _tier_union("system_", "ts, cpu_busy, samples, expected"))\n    params = []\n    for _ in config.TIERS:\n        params.extend([start, end])\n\n    hours = {}\n    for ts, cpu_busy, samples, expected in conn.execute(sql, params):\n        hour = ts - (ts % 3600)\n        a = hours.setdefault(hour, {"sum": 0, "n": 0, "peak": 0, "samples": 0})\n        a["sum"] += cpu_busy * samples\n        a["n"] += samples\n        a["peak"] = max(a["peak"], cpu_busy)\n        a["samples"] += samples\n\n    nominal = 3600 // config.INTERVAL\n    return [{"ts": hour,\n             "cpu_avg": (a["sum"] / a["n"]) / 10.0 if a["n"] else 0.0,\n             "cpu_max": a["peak"] / 10.0,\n             "coverage": min(1.0, a["samples"] / float(nominal))}\n            for hour, a in sorted(hours.items())]\n\n\ndef _like(term):\n    """A LIKE pattern that matches `term` anywhere, with the wildcards in it\n    treated as literal text.\n\n    Without escaping, searching for "_" matches every single character and\n    "%" matches everything -- so the two characters a user is most likely to\n    type when looking for a path or a percentage would return the whole\n    database.\n    """\n    escaped = term.replace("\\\\", "\\\\\\\\").replace("%", "\\\\%").replace("_", "\\\\_")\n    return "%" + escaped + "%"\n\n\ndef search(conn, term, limit=25, now=None):\n    """Everything ever recorded whose name, application or command matches.\n\n    Searches the identity table rather than the samples: identities are\n    interned once and number in the thousands, where samples number in the\n    millions. The samples are then consulted only for the handful of\n    identities that matched, to say when each was last seen and how hard it\n    ever worked -- which is what makes a result worth clicking.\n    """\n    term = (term or "").strip()\n    if not term:\n        return []\n    rows = conn.execute(\n        "SELECT id, exe, args_sig, cmdline_full, is_system, app FROM proc "\n        "WHERE exe LIKE ? ESCAPE \'\\\\\' OR app LIKE ? ESCAPE \'\\\\\' "\n        "   OR cmdline_full LIKE ? ESCAPE \'\\\\\' "\n        # An exact name first, then a name that starts with the term, then\n        # anything else: typing "arc" should not lead with a command line that\n        # happens to mention it.\n        "ORDER BY (LOWER(exe) = LOWER(?)) DESC, "\n        "         (LOWER(exe) LIKE LOWER(?) || \'%\') DESC, exe "\n        "LIMIT ?",\n        (_like(term), _like(term), _like(term), term, term, limit * 4)).fetchall()\n    if not rows:\n        return []\n\n    ids = [r[0] for r in rows]\n    placeholders = ",".join("?" * len(ids))\n    stats_sql = (\n        "SELECT proc_id, MAX(ts), MAX(cpu_max), MAX(rss_max), SUM(samples) "\n        "FROM (%s) GROUP BY proc_id"\n        % " UNION ALL ".join(\n            "SELECT proc_id, ts, cpu_max, rss_max, samples FROM sample_%s "\n            "WHERE proc_id IN (%s)" % (tier.name, placeholders)\n            for tier in config.TIERS))\n    params = []\n    for _ in config.TIERS:\n        params.extend(ids)\n    stats = {r[0]: r[1:] for r in conn.execute(stats_sql, params).fetchall()}\n\n    out = []\n    for pid, exe, args_sig, cmdline, is_system, app in rows:\n        stat = stats.get(pid)\n        if not stat:\n            # Interned but never sampled: nothing to show and nothing to click\n            # through to.\n            continue\n        last_ts, cpu_max, rss_max, samples = stat\n        out.append({\n            "exe": exe, "app": app or "", "cmdline": cmdline,\n            "args": args_sig, "is_system": bool(is_system),\n            "last_ts": last_ts, "cpu_max": (cpu_max or 0) / 10.0,\n            "rss_max": rss_max or 0, "samples": samples or 0,\n        })\n    # Ranked by how well the name matches first, and only then by how hard it\n    # worked. Sorting on CPU alone would answer "Arc" with whatever process\n    # was busiest that happens to mention arc in its command line, which is\n    # never what the person typing a name meant.\n    lowered = term.lower()\n\n    def rank(row):\n        name = row["exe"].lower()\n        app = (row["app"] or "").lower()\n        if name == lowered:\n            tier = 0                      # the process you named\n        elif app == lowered:\n            tier = 1                      # its helpers, which share the app\n        elif name.startswith(lowered):\n            tier = 2\n        elif app.startswith(lowered) or lowered in name or lowered in app:\n            tier = 3\n        else:\n            tier = 4                      # matched only in the command line\n        return (tier, -row["cpu_max"], -row["last_ts"])\n\n    out.sort(key=rank)\n    return out[:limit]\n')
_server = _install('server', '"""On-demand local dashboard server. Exits when idle.\n\nStarted by `procwatch open`, not by launchd -- this is a diagnostic tool a\nperson runs while looking at the machine, not a resident daemon. It binds\n127.0.0.1 only and shuts itself down after IDLE_TIMEOUT seconds of no\nrequests.\n"""\nimport hmac\nimport json\nimport os\nimport secrets\nimport sqlite3\nimport subprocess\nimport tempfile\nimport threading\nimport time\nimport webbrowser\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import parse_qs, urlparse\n\nfrom . import (alerts, archive, config, db, live, netstat, peers, procs,\n               query, share, storage, system)\n\nIDLE_TIMEOUT = 900\nSTATIC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "static")\n\n\ndef _token_of(server):\n    """This run\'s CSRF token, generated on first use.\n\n    serve() sets it up front; a server constructed directly (tests, or an\n    embedding caller) gets one lazily rather than an AttributeError.\n    """\n    token = getattr(server, "token", None)\n    if token is None:\n        token = secrets.token_urlsafe(24)\n        server.token = token\n    return token\n\n\ndef api_get(conn, path, params):\n    """Answer one read-only API path. Returns a JSON-able value, or None if\n    the path is not one of ours.\n\n    Split out of the request handler so the same answers can be produced\n    without one. A peer is asked for its data by running this on that machine\n    over SSH -- which means no peer has to open a port, and the reply is\n    produced by exactly the code that would have served it locally rather than\n    by a second implementation that can drift.\n    """\n    if path == "/api/series":\n        # Through float first: a caller computing a window from pixels sends\n        # fractional seconds, and refusing "1785290511.15" is pedantry about a\n        # timestamp we understand perfectly well.\n        end = _seconds(params.get("end", [time.time()])[0])\n        start = _seconds(params.get("start", [end - 86400])[0])\n        scope = params.get("scope", ["all"])[0]\n        # Clamped rather than trusted: the cost of the query scales with the\n        # count, and it arrives from a query string.\n        limit = max(1, min(60, int(params.get("limit", [12])[0])))\n        return query.series(conn, start, end, limit=limit, scope=scope)\n\n    if path == "/api/bucket":\n        tier = params.get("tier", [None])[0]\n        ts = params.get("ts", [None])[0]\n        if tier is None or ts is None:\n            raise ValueError("tier and ts are required")\n        return query.bucket_detail(conn, tier, _seconds(ts))\n\n    if path == "/api/info":\n        info = system.machine_info()\n        # This machine\'s sharing key, so it can be read off the screen rather\n        # than only from the terminal that started `share`. Local only: the\n        # relay never reaches this branch for a peer, because a peer answers\n        # /api/info with its own -- and a device\'s key is not something the\n        # dashboard should be able to collect from the machines it watches.\n        try:\n            info["share_key"] = share.key(conn)\n            info["share_host"] = share.local_address()\n            info["share_port"] = share.DEFAULT_PORT\n            # Present only when this Mac is on a private network. When it is,\n            # it is the address to hand out: it works from anywhere and the\n            # traffic is encrypted, which the local one is not.\n            info["share_vpn"] = share.tailscale_address()\n        except Exception:\n            info["share_key"] = ""\n            info["share_host"] = ""\n        # This machine\'s own clock. Two Macs can disagree by hours -- these\n        # two do -- so anything derived from a timestamp has to be worked out\n        # against the clock that produced it. Without this a peer\'s "last\n        # sample" age and every chart window are computed from the wrong one.\n        info["now"] = int(time.time())\n        info["last_tick"] = conn.execute(\n            "SELECT MAX(updated_ts) FROM sampler_state").fetchone()[0]\n        try:\n            info["db_bytes"] = os.path.getsize(config.DB_PATH)\n        except OSError:\n            info["db_bytes"] = 0\n        # The oldest sample anywhere, so a pan stops at the edge of what was\n        # recorded rather than scrolling into a window that can only be empty.\n        first = None\n        for tier in config.TIERS:\n            row = conn.execute(\n                "SELECT MIN(ts) FROM sample_%s" % tier.name).fetchone()\n            if row and row[0] is not None:\n                first = row[0] if first is None else min(first, row[0])\n        info["first_ts"] = first\n        return info\n\n    if path == "/api/activity":\n        days = max(1, min(370, int(params.get("days", ["30"])[0])))\n        now = int(time.time())\n        return query.activity(conn, now - days * 86400, now)\n\n    if path == "/api/ports":\n        return netstat.listeners()\n\n    if path == "/api/now":\n        # Reads the machine directly and writes nothing.\n        return live.snapshot()\n\n    if path == "/api/live":\n        return procs.live_tree()\n\n    if path == "/api/storage":\n        return storage.usage(conn, limit=30)\n\n    if path == "/api/alerts":\n        return {"rules": alerts.rules(conn),\n                "events": alerts.recent(conn, limit=40),\n                "metrics": alerts.METRICS}\n\n    if path == "/api/search":\n        return query.search(conn, params.get("q", [""])[0], limit=25)\n\n    return None\n\n\ndef _csv(text):\n    """One CSV field.\n\n    Process names contain commas ("Arc Helper (Renderer), v2") and quotes, and\n    a spreadsheet reading an unescaped one silently shifts every column after\n    it -- which looks like data rather than damage.\n    """\n    text = "" if text is None else str(text)\n    if any(c in text for c in \',"\\n\\r\'):\n        return \'"\' + text.replace(\'"\', \'""\') + \'"\'\n    return text\n\n\ndef _seconds(value):\n    """A whole-second timestamp from a query parameter.\n\n    Accepts "1785290511" and "1785290511.153447" alike; still raises\n    ValueError on anything that is not a number, which the caller turns into\n    a 400 rather than guessing.\n    """\n    return int(float(value))\n\n\nclass Handler(BaseHTTPRequestHandler):\n    def log_message(self, *args):\n        pass\n\n    def _send(self, code, body, content_type):\n        payload = body if isinstance(body, bytes) else body.encode()\n        self.send_response(code)\n        self.send_header("Content-Type", content_type)\n        self.send_header("Content-Length", str(len(payload)))\n        # Nothing here is ever worth caching: the API is live data and the\n        # page changes whenever the dashboard is edited. Without this a\n        # reload can serve a stale page indefinitely, which looks exactly\n        # like a broken build.\n        self.send_header("Cache-Control", "no-store, must-revalidate")\n        self.end_headers()\n        self.wfile.write(payload)\n\n    def do_GET(self):\n        self.server.last_seen = time.time()\n        parsed = urlparse(self.path)\n        params = parse_qs(parsed.query)\n        if parsed.path in ("/", "/index.html"):\n            return self._serve_index()\n        if parsed.path == "/api/peers":\n            return self._send(200, json.dumps(peers.listing()), "application/json")\n        if parsed.path == "/api/remote":\n            return self._send_remote(params)\n        conn = db.connect(config.DB_PATH)\n        try:\n            if parsed.path == "/api/export":\n                return self._send_export(conn, params)\n            if parsed.path == "/api/backup":\n                return self._send_backup()\n            payload = api_get(conn, parsed.path, params)\n            if payload is None:\n                return self._send(404, "not found", "text/plain")\n            self._send(200, json.dumps(payload), "application/json")\n        except ValueError as exc:\n            # Bad int params (start/end/ts) and query.bucket_detail\'s unknown-\n            # tier guard both land here; both are the caller\'s fault.\n            self._send(400, str(exc), "text/plain")\n        finally:\n            conn.close()\n\n    def do_POST(self):\n        """The mutating endpoints: signal a process, and change alert rules.\n\n        Restricted to processes the calling user owns, which is also all the\n        kernel would permit without privilege. The check is here so the\n        failure is a legible message rather than a permission error, and so a\n        typo cannot aim a signal at a system daemon by accident.\n        """\n        self.server.last_seen = time.time()\n        parsed = urlparse(self.path)\n        if parsed.path not in ("/api/kill", "/api/alerts", "/api/peers"):\n            return self._send(404, "not found", "text/plain")\n        # Same guard for both. Changing a rule is far less dangerous than\n        # signalling a process, but a page on another origin still has no\n        # business silencing someone\'s alerts.\n        refusal = self._reject_cross_origin()\n        if refusal:\n            return self._send(403, json.dumps({"ok": False, "error": refusal}),\n                              "application/json")\n        if parsed.path == "/api/alerts":\n            return self._change_alert()\n        if parsed.path == "/api/peers":\n            return self._change_peer()\n        try:\n            length = int(self.headers.get("Content-Length") or 0)\n            body = json.loads(self.rfile.read(length) or b"{}")\n            pid = int(body["pid"])\n            signal_name = body.get("signal", "TERM")\n        except (ValueError, KeyError, TypeError):\n            return self._send(400, json.dumps({"ok": False, "error": "pid required"}),\n                              "application/json")\n        result = procs.signal_pid(pid, signal_name)\n        code = 200 if result["ok"] else 400\n        self._send(code, json.dumps(result), "application/json")\n\n    def _change_alert(self):\n        try:\n            length = int(self.headers.get("Content-Length") or 0)\n            body = json.loads(self.rfile.read(length) or b"{}")\n        except ValueError:\n            return self._send(400, json.dumps({"error": "malformed request"}),\n                              "application/json")\n        conn = db.connect(config.DB_PATH)\n        try:\n            action = body.get("action")\n            if action == "add":\n                alerts.add(conn, str(body.get("pattern") or "*"),\n                           str(body.get("metric") or "cpu"),\n                           float(body.get("threshold", 80)),\n                           int(body.get("sustain", 600)))\n            elif action == "remove":\n                alerts.remove(conn, int(body["id"]))\n            else:\n                return self._send(400, json.dumps({"error": "unknown action"}),\n                                  "application/json")\n            return self._send(200, json.dumps({"ok": True,\n                                               "rules": alerts.rules(conn)}),\n                              "application/json")\n        except (ValueError, KeyError, TypeError) as error:\n            return self._send(400, json.dumps({"error": str(error)}),\n                              "application/json")\n        finally:\n            conn.close()\n\n    def do_OPTIONS(self):\n        """Refuse preflight explicitly.\n\n        Answering it with permissive CORS headers is what would let a hostile\n        page through; declining is the whole point, so it is stated here\n        rather than left to the base class\'s 501.\n        """\n        self._send(403, "cross-origin requests are not served", "text/plain")\n\n    def _reject_cross_origin(self):\n        """Return an error string if this request could be a forged one.\n\n        Binding 127.0.0.1 keeps other machines out; it does nothing about the\n        browser already on this one. Any page the user visits can POST to\n        localhost, and with Content-Type text/plain that is a CORS "simple\n        request" -- no preflight, sent straight through. The attacker cannot\n        read the reply, but a process is already dead by then. Verified\n        against this very endpoint before these checks existed.\n\n        Four layers, because each covers a different escape:\n          - a JSON Content-Type is not a simple request, so it forces a\n            preflight the server never answers;\n          - a custom header cannot be set cross-origin without that same\n            preflight;\n          - Origin, when the browser sends it, must be our own;\n          - a token minted per server run and readable only by same-origin\n            script, so a blind cross-origin POST cannot guess it.\n        """\n        ctype = (self.headers.get("Content-Type") or "").split(";")[0].strip()\n        if ctype != "application/json":\n            return "Content-Type must be application/json"\n        if self.headers.get("X-Procwatch") != "1":\n            return "missing X-Procwatch header"\n        origin = self.headers.get("Origin")\n        allowed = getattr(self.server, "allowed_origins", None)\n        if origin and allowed is not None and origin not in allowed:\n            return "cross-origin request refused"\n        token = self.headers.get("X-Procwatch-Token")\n        if not token or not hmac.compare_digest(token, _token_of(self.server)):\n            return "bad or missing session token"\n        return None\n\n    def _change_peer(self):\n        try:\n            length = int(self.headers.get("Content-Length") or 0)\n            body = json.loads(self.rfile.read(length) or b"{}")\n        except ValueError:\n            return self._send(400, json.dumps({"error": "malformed request"}),\n                              "application/json")\n        try:\n            action = body.get("action")\n            if action == "add":\n                peers.add(str(body.get("name") or ""),\n                          str(body.get("host") or ""),\n                          str(body.get("key") or ""))\n            elif action == "remove":\n                peers.remove(str(body.get("name") or ""))\n            else:\n                return self._send(400, json.dumps({"error": "unknown action"}),\n                                  "application/json")\n        except (ValueError, KeyError, TypeError) as error:\n            return self._send(400, json.dumps({"error": str(error)}),\n                              "application/json")\n        self._send(200, json.dumps({"ok": True, "peers": peers.listing()}),\n                   "application/json")\n\n    def _send_remote(self, params):\n        """Relay one read-only API path to a peer over SSH.\n\n        Only the read side: there is no remote kill, and there is not going to\n        be one behind a proxy the browser can reach. Ending a process on\n        another machine deserves to be a decision made on that machine.\n\n        The path is checked against the ones this server itself answers, so a\n        crafted value cannot become an argument to something else on the far\n        side, and only the peer\'s name comes from the caller -- the host and\n        the program path come from the local peer list.\n        """\n        name = params.get("peer", [""])[0]\n        path = params.get("path", ["/api/info"])[0]\n        if not path.startswith("/api/") or path in ("/api/remote", "/api/peers",\n                                                    "/api/backup", "/api/export"):\n            return self._send(400, json.dumps({"error": "not a relayable path"}),\n                              "application/json")\n        forwarded = {k: v for k, v in params.items()\n                     if k not in ("peer", "path")}\n        try:\n            payload = peers.fetch(name, path, forwarded)\n        except KeyError:\n            return self._send(404, json.dumps({"error": "no such device"}),\n                              "application/json")\n        except (RuntimeError, OSError) as error:\n            return self._send(502, json.dumps({"error": str(error)[:300]}),\n                              "application/json")\n        except subprocess.TimeoutExpired:\n            return self._send(504, json.dumps(\n                {"error": "%s did not answer in time" % name}),\n                "application/json")\n        self._send(200, json.dumps(payload), "application/json")\n\n    def _send_export(self, conn, params):\n        """The window on screen as CSV.\n\n        The backup is the whole database in SQLite\'s own format, which is the\n        right thing for keeping and the wrong thing for a spreadsheet. This is\n        one row per process per bucket over one window -- what you would paste\n        into a spreadsheet to ask a question this dashboard does not answer.\n        """\n        end = _seconds(params.get("end", [time.time()])[0])\n        start = _seconds(params.get("start", [end - 86400])[0])\n        scope = params.get("scope", ["all"])[0]\n        limit = max(1, min(60, int(params.get("limit", [12])[0])))\n        data = query.series(conn, start, end, limit=limit, scope=scope)\n        lines = ["time,process,application,cpu_avg_percent,cpu_max_percent,"\n                 "memory_bytes,processes,net_in_bytes,net_out_bytes,"\n                 "disk_read_bytes,disk_write_bytes"]\n        for series in data["series"]:\n            name = series["exe"]\n            app = series.get("app", "")\n            for point in series["points"]:\n                lines.append(",".join([\n                    time.strftime("%Y-%m-%d %H:%M:%S",\n                                  time.localtime(point["ts"])),\n                    _csv(name), _csv(app),\n                    "%.2f" % point["cpu_avg"], "%.2f" % point["cpu_max"],\n                    "%d" % int(point["rss_avg"] * 1024),\n                    "%d" % point["nproc"],\n                    "%d" % point["net_in"], "%d" % point["net_out"],\n                    "%d" % point["disk_read"], "%d" % point["disk_write"]]))\n        body = ("\\n".join(lines) + "\\n").encode("utf-8")\n        self.send_response(200)\n        self.send_header("Content-Type", "text/csv; charset=utf-8")\n        self.send_header("Content-Length", str(len(body)))\n        self.send_header("Content-Disposition",\n                         \'attachment; filename="procwatch-%s.csv"\'\n                         % time.strftime("%Y-%m-%d-%H%M", time.localtime(end)))\n        self.send_header("Cache-Control", "no-store, must-revalidate")\n        self.end_headers()\n        self.wfile.write(body)\n\n    def _send_backup(self):\n        """A consistent snapshot of the database, as a download.\n\n        Written to a temporary file first rather than assembled in memory: a\n        year of history is a few hundred megabytes, and the point of a backup\n        is that it works when things are already going badly.\n\n        Read-only and idempotent, so it belongs on GET -- but for that same\n        reason it is not behind the CSRF check that guards /api/kill, and a\n        page on another origin could point a user\'s browser at it. It can only\n        ever return this user\'s own history to this user\'s own machine, which\n        is what the dashboard already shows them.\n        """\n        handle, temp = tempfile.mkstemp(prefix="procwatch-backup-", suffix=".db")\n        os.close(handle)\n        try:\n            archive.backup(temp)\n            with open(temp, "rb") as source:\n                payload = source.read()\n        except (RuntimeError, OSError, sqlite3.Error) as error:\n            return self._send(500, "backup failed: %s" % error, "text/plain")\n        finally:\n            for leftover in (temp, temp + "-wal", temp + "-shm"):\n                if os.path.exists(leftover):\n                    os.remove(leftover)\n        self.send_response(200)\n        self.send_header("Content-Type", "application/vnd.sqlite3")\n        self.send_header("Content-Length", str(len(payload)))\n        self.send_header("Content-Disposition",\n                         \'attachment; filename="%s"\' % archive.default_name())\n        self.send_header("Cache-Control", "no-store, must-revalidate")\n        self.end_headers()\n        self.wfile.write(payload)\n\n    def _serve_index(self):\n        """Serve the page with this run\'s token embedded.\n\n        Same-origin script can read it; a cross-origin page cannot read this\n        response at all, which is what makes the token worth anything.\n        """\n        try:\n            with open(os.path.join(STATIC, "index.html"), "r") as handle:\n                page = handle.read()\n        except FileNotFoundError:\n            return self._send(404, "no dashboard installed", "text/plain")\n        page = page.replace("__PROCWATCH_TOKEN__", _token_of(self.server))\n        self._send(200, page.encode(), "text/html; charset=utf-8")\n\n\ndef serve(port, open_browser=True, idle_timeout=IDLE_TIMEOUT):\n    if not os.path.exists(config.DB_PATH):\n        print("no database yet; run `procwatch install` and wait a minute")\n        return 1\n    httpd = ThreadingHTTPServer(("127.0.0.1", port), Handler)\n    httpd.last_seen = time.time()\n    # Minted per run, so a token lifted from one session is useless against\n    # the next, and nothing needs to be stored on disk.\n    httpd.token = secrets.token_urlsafe(24)\n    httpd.allowed_origins = {"http://127.0.0.1:%d" % port,\n                             "http://localhost:%d" % port}\n\n    def reap():\n        while time.time() - httpd.last_seen < idle_timeout:\n            time.sleep(30)\n        httpd.shutdown()\n\n    # idle_timeout=None keeps it up indefinitely, which is what the menu bar\n    # app wants: it owns the lifetime and quitting it stops the server.\n    if idle_timeout is not None:\n        threading.Thread(target=reap, daemon=True).start()\n    live.start_network_refresh()\n    url = "http://127.0.0.1:%d/" % port\n    print("serving %s%s" % (url, "  (exits after %d minutes idle)" % (idle_timeout // 60)\n                            if idle_timeout else ""))\n    if open_browser:\n        webbrowser.open(url)\n    httpd.serve_forever()\n    return 0\n')
_launchd = _install('launchd', '"""Generate and load the launchd agent."""\nimport os\nimport plistlib\nimport subprocess\nimport sys\n\nfrom . import config\n\nLABEL = "dev.procwatch.sampler"\nPLIST_PATH = os.path.expanduser("~/Library/LaunchAgents/%s.plist" % LABEL)\n\n\ndef entry_point():\n    """How launchd should re-invoke this code, and from where.\n\n    Two shapes have to work. From a checkout, `-m procwatch.main` resolves\n    against the package directory. From the single-file build there is no\n    package directory -- `__path__` is empty -- and `-m` would resolve to\n    nothing, so the agent is pointed at the script itself.\n\n    Getting this wrong is silent: launchd accepts the job, runs it every 30\n    seconds, and every run fails. So an unusable answer raises instead.\n    """\n    package = sys.modules.get(__package__ or "procwatch")\n    bundled = not getattr(package, "__path__", None)\n    if bundled:\n        script = os.path.abspath(sys.argv[0]) if sys.argv and sys.argv[0] else ""\n        if not (script.endswith(".py") and os.path.isfile(script)):\n            raise RuntimeError(\n                "cannot locate procwatch.py to schedule; run the installer, or "\n                "invoke it as `python3 /full/path/to/procwatch.py install`")\n        return [sys.executable, script, "record"], os.path.dirname(script)\n    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n    return [sys.executable, "-m", "procwatch.main"], root\n\n\ndef plist_text(arguments, working_dir):\n    payload = {\n        "Label": LABEL,\n        "ProgramArguments": arguments,\n        "StartInterval": config.INTERVAL,\n        "RunAtLoad": True,\n        "KeepAlive": False,\n        "WorkingDirectory": working_dir,\n        "StandardErrorPath": config.LOG_PATH,\n    }\n    return plistlib.dumps(payload).decode()\n\n\ndef install():\n    config.ensure_dirs()\n    os.makedirs(os.path.dirname(PLIST_PATH), exist_ok=True)\n    arguments, working_dir = entry_point()\n    with open(PLIST_PATH, "w") as handle:\n        handle.write(plist_text(arguments, working_dir))\n    subprocess.run(["launchctl", "unload", PLIST_PATH], capture_output=True)\n    subprocess.run(["launchctl", "load", PLIST_PATH], check=True)\n    return PLIST_PATH\n\n\ndef uninstall():\n    subprocess.run(["launchctl", "unload", PLIST_PATH], capture_output=True)\n    if os.path.exists(PLIST_PATH):\n        os.remove(PLIST_PATH)\n')
_main = _install('main', '# procwatch/main.py\n"""The launchd entry point. One tick, then exit.\n\nStateless by design: launchd respawns this every INTERVAL seconds, so nothing\nsurvives in memory and sampler_state is the only carrier between ticks. A\nresident daemon would hold memory forever, which is the problem this tool\nexists to detect.\n"""\nimport sys\nimport time\nimport traceback\n\nfrom . import (alerts, config, db, identity, netstat, psreader, rollup,\n               rusage, sampler, storage, system)\n\n\ndef _log(message):\n    config.ensure_dirs()\n    with open(config.LOG_PATH, "a") as handle:\n        handle.write("%s %s\\n" % (time.strftime("%Y-%m-%dT%H:%M:%S"), message))\n\n\ndef run_once(now=None):\n    now = int(time.time()) if now is None else now\n    try:\n        config.ensure_dirs()\n        procs = psreader.read()\n        readings = system.read()\n    except Exception as error:          # a bad read must not kill the agent\n        _log("sample failed: %s" % error)\n        _log(traceback.format_exc().strip())\n        return 1\n\n    # Network and disk are best-effort: nettop reports only processes that\n    # touched the network, and libproc refuses other users\' processes. Neither\n    # is worth failing a tick over, so a failure here costs those columns and\n    # nothing else -- CPU and memory still record.\n    extra = {}\n    try:\n        net = netstat.read()\n        ru = rusage.read_all([p.pid for p in procs])\n        for proc in procs:\n            n = net.get(proc.pid, (0, 0))\n            r = ru.get(proc.pid)\n            extra[proc.pid] = (n[0], n[1],\n                               r[0] if r else 0, r[1] if r else 0,\n                               r[4] if r else 0)\n    except Exception as error:\n        _log("extra counters unavailable this tick: %s" % error)\n        extra = {}\n\n    try:\n        battery = system.battery()\n    except Exception:\n        battery = None\n\n    conn = None\n    try:\n        conn = db.connect(config.DB_PATH)\n        db.init_schema(conn)\n        sampler.tick(conn, procs, readings, now, extra, battery,\n                     identity.classify(procs), identity.apps(procs))\n        rollup.run(conn, now)\n        rollup.disk_guard(conn, now, system.free_bytes())\n        # Rules are checked against the rows just written. A rule that cannot\n        # be evaluated must not cost the tick its sample, which is the only\n        # thing here that cannot be recovered later.\n        try:\n            for event in alerts.evaluate(conn, now):\n                alerts.notify(event)\n        except Exception as error:\n            _log("alert evaluation failed: %s" % error)\n        # Disk usage is a size, not a rate: it moves once a week and costs a\n        # filesystem walk to measure, so it runs once a day. Last, so a slow\n        # walk cannot delay the sample -- that is already written and\n        # committed by this point.\n        try:\n            if storage.due(conn):\n                storage.scan(conn)\n        except Exception as error:\n            _log("storage scan failed: %s" % error)\n        return 0\n    except Exception as error:\n        _log("write failed: %s" % error)\n        _log(traceback.format_exc().strip())\n        return 1\n    finally:\n        if conn is not None:\n            conn.close()\n\n\ndef main():\n    return run_once()\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n')
_cli = _install('cli', '"""procwatch install | open | serve | record | share | key | peer | app |\nbackup | restore | alert | status | uninstall"""\nimport argparse\nimport json\nimport os\nimport sys\nimport time\n\nfrom . import alerts, appbuild, archive, config, db, launchd, peers, share\n\n\ndef _status():\n    if not os.path.exists(config.DB_PATH):\n        print("no database yet; run `procwatch install`")\n        return 1\n    conn = db.connect(config.DB_PATH)\n    size_mb = os.path.getsize(config.DB_PATH) / (1024.0 * 1024.0)\n    print("database   %s  (%.1f MB actual)" % (config.DB_PATH, size_mb))\n    last = conn.execute("SELECT MAX(updated_ts) FROM sampler_state").fetchone()[0]\n    if last:\n        print("last tick  %s (%d s ago)"\n              % (time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(last)),\n                 int(time.time()) - last))\n    for tier in config.TIERS:\n        row = conn.execute(\n            "SELECT COUNT(*), MIN(ts), MAX(ts) FROM sample_%s" % tier.name).fetchone()\n        span = "empty" if not row[1] else "%.1f days" % ((row[2] - row[1]) / 86400.0)\n        print("%-9s %8d rows  %s" % (tier.name, row[0], span))\n    gaps = conn.execute("SELECT COUNT(*) FROM gap").fetchone()[0]\n    print("gaps       %d recorded" % gaps)\n    return 0\n\n\ndef _fetch(path, query):\n    """Print one API answer as JSON. This is what a peer runs when asked."""\n    from urllib.parse import parse_qs\n    from . import server\n    conn = db.connect(config.DB_PATH)\n    try:\n        payload = server.api_get(conn, path, parse_qs(query))\n    except ValueError as error:\n        print(json.dumps({"error": str(error)}), file=sys.stderr)\n        return 1\n    finally:\n        conn.close()\n    if payload is None:\n        print(json.dumps({"error": "unknown path %s" % path}), file=sys.stderr)\n        return 1\n    print(json.dumps(payload))\n    return 0\n\n\ndef _peer(args):\n    if args.action == "add":\n        if not args.name or not args.host:\n            print("usage: procwatch peer add <name> <ssh-host>", file=sys.stderr)\n            return 1\n        try:\n            where = peers.add(args.name, args.host, args.key)\n        except ValueError as error:\n            print(error, file=sys.stderr)\n            return 1\n        if not args.key:\n            print("added %s at %s, but with no key -- it will be refused.\\n"\n                  "Run `procwatch share` on that machine and pass the three "\n                  "words it prints with --key." % (args.name, where),\n                  file=sys.stderr)\n    elif args.action == "remove":\n        if not args.name or not peers.remove(args.name):\n            print("no peer called %r" % args.name, file=sys.stderr)\n            return 1\n    elif args.action == "check":\n        names = [args.name] if args.name else [p["name"] for p in peers.listing()]\n        if not names:\n            print("no peers yet")\n            return 0\n        for name in names:\n            state = peers.check(name)\n            if state["ok"]:\n                age = state["last_tick_age"]\n                print("%-16s ok  %s  last sample %s"\n                      % (name, state.get("hostname") or "",\n                         "%ds ago" % age if age is not None else "never"))\n            else:\n                print("%-16s unreachable  %s" % (name, state["error"]))\n        return 0\n\n    current = peers.listing()\n    if not current:\n        print("no peers. Add one:\\n"\n              "  procwatch peer add laptop user@host.example")\n        return 0\n    for peer in current:\n        print("%-16s %s" % (peer["name"], peer["host"]))\n    return 0\n\n\ndef _restore(path, assume_yes):\n    """Replace the recorded history with a file, after saying what that means.\n\n    This is the only command that can destroy data, so unless it is told not\n    to it describes both databases and waits for a yes. The one being\n    replaced is copied aside regardless.\n    """\n    print("restore from  %s\\n              %s" % (path, archive.describe(path)))\n    if os.path.exists(config.DB_PATH):\n        print("replacing     %s\\n              %s"\n              % (config.DB_PATH, archive.describe(config.DB_PATH)))\n    if not assume_yes:\n        try:\n            if input("\\nReplace the recorded history? [y/N] ").strip().lower() \\\n                    not in ("y", "yes"):\n                print("nothing changed")\n                return 1\n        except EOFError:\n            print("no answer; nothing changed", file=sys.stderr)\n            return 1\n    try:\n        target, previous = archive.restore(path)\n    except (RuntimeError, OSError) as error:\n        print("restore failed: %s" % error, file=sys.stderr)\n        return 1\n    print("restored %s" % target)\n    if previous:\n        print("the replaced database is at %s" % previous)\n    return 0\n\n\ndef _alert(args):\n    """Add, list or remove a rule.\n\n    This command used to write to a `watchlist` table that nothing ever read.\n    It has been a no-op in every release; now it does what its name promised.\n    """\n    config.ensure_dirs()\n    conn = db.connect(config.DB_PATH)\n    db.init_schema(conn)\n    alerts.init(conn)\n    try:\n        if args.remove is not None:\n            if not alerts.remove(conn, args.remove):\n                print("no rule with id %d" % args.remove, file=sys.stderr)\n                return 1\n        elif args.pattern is not None:\n            alerts.add(conn, args.pattern, args.metric, args.threshold,\n                       args.sustain)\n    except ValueError as error:\n        print(error, file=sys.stderr)\n        return 1\n    current = alerts.rules(conn)\n    if not current:\n        print("no rules. Add one:\\n"\n              "  procwatch alert \'*\' --metric cpu --above 80 --for 10m")\n        return 0\n    for rule in current:\n        print("%-4d %-20s %-7s above %g%s for %s%s"\n              % (rule["id"], rule["pattern"], rule["metric"], rule["threshold"],\n                 alerts.METRICS[rule["metric"]]["unit"],\n                 alerts._duration(rule["sustain"]),\n                 "" if rule["enabled"] else "  (disabled)"))\n    return 0\n\n\ndef _duration_arg(text):\n    """"10m", "2h", "45s" or bare seconds -- because nobody thinks in seconds."""\n    text = str(text).strip().lower()\n    units = {"s": 1, "m": 60, "h": 3600}\n    if text and text[-1] in units:\n        return int(float(text[:-1]) * units[text[-1]])\n    return int(float(text))\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(prog="procwatch")\n    sub = parser.add_subparsers(dest="command", required=True)\n    sub.add_parser("install")\n    sub.add_parser("uninstall")\n    sub.add_parser("status")\n    # The launchd agent\'s entry point. Named rather than reached through\n    # `-m procwatch.main`, because the single-file build has no package\n    # directory for -m to find and the agent must work from either form.\n    sub.add_parser("record")\n    opener = sub.add_parser("open")\n    opener.add_argument("--port", type=int, default=8787)\n    # Serving without opening a browser or reaping an idle server: the menu\n    # bar app owns the lifetime, and a closed panel is not a reason to stop.\n    server_cmd = sub.add_parser("serve")\n    server_cmd.add_argument("--port", type=int, default=8790)\n    saver = sub.add_parser("backup")\n    saver.add_argument("path", nargs="?", default=".",\n                       help="file, or a directory to put a dated file in")\n    loader = sub.add_parser("restore")\n    loader.add_argument("path")\n    loader.add_argument("--yes", action="store_true",\n                        help="skip the confirmation prompt")\n    # How a peer answers: run the same read-only API locally and print it.\n    # Not a network service -- it reads stdin-less arguments and writes JSON,\n    # so the only way to reach it is to already have shell access.\n    fetcher = sub.add_parser("fetch")\n    fetcher.add_argument("path")\n    fetcher.add_argument("query", nargs="?", default="")\n\n    peerer = sub.add_parser("peer")\n    peerer.add_argument("action", choices=["add", "list", "remove", "check"],\n                        nargs="?", default="list")\n    peerer.add_argument("name", nargs="?")\n    peerer.add_argument("host", nargs="?")\n    peerer.add_argument("--key", default="",\n                        help="the three words that machine printed")\n\n    keyer = sub.add_parser("key")\n    keyer.add_argument("--new", action="store_true",\n                       help="forget the old key and make a new one")\n\n    sharer = sub.add_parser("share")\n    sharer.add_argument("--port", type=int, default=share.DEFAULT_PORT)\n    sharer.add_argument("--new-key", action="store_true",\n                        help="forget the old key and print a new one")\n\n    builder = sub.add_parser("app")\n    builder.add_argument("--to", default="/Applications")\n    alerter = sub.add_parser("alert")\n    alerter.add_argument("pattern", nargs="?",\n                         help="process or application name, or * for anything")\n    alerter.add_argument("--metric", default="cpu",\n                         choices=sorted(alerts.METRICS))\n    alerter.add_argument("--above", dest="threshold", type=float, default=80.0)\n    alerter.add_argument("--for", dest="sustain", type=_duration_arg,\n                         default="10m",\n                         help="how long it must hold: 30s, 10m, 2h")\n    alerter.add_argument("--remove", type=int, metavar="ID")\n\n    args = parser.parse_args(argv)\n    if args.command == "install":\n        print("loaded %s" % launchd.install())\n        return 0\n    if args.command == "uninstall":\n        launchd.uninstall()\n        print("unloaded; database left at %s" % config.DB_PATH)\n        return 0\n    if args.command == "status":\n        return _status()\n    if args.command == "backup":\n        try:\n            written = archive.backup(args.path)\n        except (RuntimeError, OSError) as error:\n            print("backup failed: %s" % error, file=sys.stderr)\n            return 1\n        print("%s\\n%s" % (written, archive.describe(written)))\n        return 0\n    if args.command == "restore":\n        return _restore(args.path, args.yes)\n    if args.command == "fetch":\n        return _fetch(args.path, args.query)\n    if args.command == "peer":\n        return _peer(args)\n    if args.command == "key":\n        conn = db.connect(config.DB_PATH)\n        try:\n            secret = share.key(conn, reset=args.new)\n        finally:\n            conn.close()\n        print(secret)\n        return 0\n    if args.command == "share":\n        return share.serve(args.port, reset=args.new_key)\n    if args.command == "app":\n        try:\n            path = appbuild.build(args.to)\n        except (RuntimeError, OSError) as error:\n            print(error, file=sys.stderr)\n            return 1\n        print("installed %s" % path)\n        appbuild.launch(path)\n        return 0\n    if args.command == "alert":\n        return _alert(args)\n    if args.command == "record":\n        from . import main as recorder\n        return recorder.run_once()\n    if args.command == "serve":\n        from . import server\n        return server.serve(args.port, open_browser=False, idle_timeout=None)\n    if args.command == "open":\n        from . import server\n        return server.serve(args.port)\n    return 1\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n')

